window.POEM_STUDIES = {"poem-1":{"title":"咏鹅","intro":"“咏”是用诗歌描写、赞美；题目就是赞美鹅。","theme":"诗从声音写到姿态，再写颜色与动作，表现观察鹅时的欢喜。连说三个“鹅”，像孩子兴奋地呼唤；白与绿、红与清相互映衬。","glossary":[{"word":"鹅","meaning":"一种颈长、善游水的家禽"},{"word":"曲项","meaning":"弯着脖子，曲是弯曲，项是脖子"},{"word":"向天","meaning":"朝着天空"},{"word":"歌","meaning":"这里指鹅的鸣叫"},{"word":"白毛","meaning":"白色的羽毛"},{"word":"浮","meaning":"漂在水面"},{"word":"绿水","meaning":"碧绿的水"},{"word":"红掌","meaning":"鹅红色的脚掌"},{"word":"拨","meaning":"划动"},{"word":"清波","meaning":"清澈水面上的波纹"}],"lines":[{"translations":["鹅呀，鹅呀，鹅呀！","你弯着脖子，朝着天空鸣叫。"],"reading":"先听到声音，再看到仰头的姿态，写出了鹅神气活泼的样子。","clauses":["鹅，鹅，鹅，","曲项向天歌。"]},{"translations":["白色的羽毛浮在碧绿的水面上。","红色的脚掌划动着清澈的水波。"],"reading":"“浮”写身体轻轻漂着，“拨”写脚掌用力划水，一静一动很具体。","clauses":["白毛浮绿水，","红掌拨清波。"]}]},"poem-2":{"title":"江南","intro":"汉乐府民歌，描写江南采莲时的景象。“乐府”原与采集、演唱诗歌的机构有关。","theme":"荷叶繁盛，鱼儿自在，反复的方位词使歌声轻快，表现水乡劳动生活的生气与欢乐。","glossary":[{"word":"江南","meaning":"长江以南地区，这里指水乡"},{"word":"可","meaning":"可以，也有正好、适宜的意味"},{"word":"采莲","meaning":"采摘莲蓬或莲子"},{"word":"莲叶","meaning":"荷叶"},{"word":"何","meaning":"多么"},{"word":"田田","meaning":"荷叶茂盛、相连的样子"},{"word":"鱼戏","meaning":"鱼儿游动嬉戏"},{"word":"间","meaning":"中间"},{"word":"东","meaning":"东边"},{"word":"西","meaning":"西边"},{"word":"南","meaning":"南边"},{"word":"北","meaning":"北边"}],"lines":[{"translations":["江南正是适宜采莲的地方。","荷叶长得多么茂盛，连成一片！"],"reading":"“何田田”带赞叹语气，重在表现荷叶的繁盛，不是田地很多。","clauses":["江南可采莲，","莲叶何田田。"]},{"translations":["鱼儿在荷叶之间嬉戏。"],"reading":"“戏”把鱼写得像玩耍的孩子，画面一下活了起来。","clauses":["鱼戏莲叶间。"]},{"translations":["鱼儿一会儿游到荷叶东边。","一会儿又游到荷叶西边。"],"reading":"东西相对，写出鱼游动的自由，也便于歌唱时反复咏唱。","clauses":["鱼戏莲叶东，","鱼戏莲叶西，"]},{"translations":["鱼儿一会儿游到荷叶南边。","一会儿又游到荷叶北边。"],"reading":"南北接着东西，不必理解为严格的行进路线，而是四处穿梭。","clauses":["鱼戏莲叶南，","鱼戏莲叶北。"]}]},"poem-3":{"title":"画","intro":"写的是画中的景物，也常作一首猜画的谜语诗；作者归属存在不同说法。","theme":"远近、声色、来去形成对照。现实中的花会谢、鸟会惊，而画中的形象静止，正好点明画的特点。","glossary":[{"word":"远看","meaning":"从远处看"},{"word":"山有色","meaning":"山有鲜明的颜色"},{"word":"近听","meaning":"走近去听"},{"word":"无声","meaning":"没有声音"},{"word":"春去","meaning":"春天过去"},{"word":"还","meaning":"仍然"},{"word":"在","meaning":"存在、留着"},{"word":"人来","meaning":"有人走近"},{"word":"鸟不惊","meaning":"鸟儿不会因人靠近而受惊"},{"word":"水","meaning":"画中的流水"},{"word":"花","meaning":"画中开放的花"}],"lines":[{"translations":["远远看去，山有清楚的颜色。","走近听，流水却没有声音。"],"reading":"山能看见，水却听不见，暗示这不是眼前真实的山水。","clauses":["远看山有色，","近听水无声。"]},{"translations":["春天过去了，花仍然开着。","人走近了，鸟儿也不受惊。"],"reading":"画中的花鸟不随季节和人的动作变化，由此可以猜出谜底“画”。","clauses":["春去花还在，","人来鸟不惊。"]}]},"poem-4":{"title":"悯农·其二","intro":"“悯”是怜悯、体恤；诗让读者理解农民劳作的辛苦。","theme":"先写烈日下的劳动，再追问粮食从哪里来。重点是尊重劳动和珍惜粮食，不能只把它当成劝人吃完饭的口号。","glossary":[{"word":"锄禾","meaning":"给禾苗松土除草"},{"word":"日当午","meaning":"太阳正在头顶，指正午"},{"word":"汗","meaning":"汗水"},{"word":"滴","meaning":"一滴滴落下"},{"word":"禾下土","meaning":"禾苗下面的泥土"},{"word":"谁知","meaning":"有谁懂得，带提醒、感叹语气"},{"word":"盘中餐","meaning":"盘中的饭食"},{"word":"粒粒","meaning":"每一粒粮食"},{"word":"皆","meaning":"都"},{"word":"辛苦","meaning":"这里指辛勤劳动换来的成果"}],"lines":[{"translations":["农民在正午的烈日下锄草。","汗水一滴滴落进禾苗下的泥土。"],"reading":"“日当午”交代最热的时段，“汗滴”把看不见的劳苦变成具体画面。","clauses":["锄禾日当午，","汗滴禾下土。"]},{"translations":["有谁真正懂得盘中的饭食呢？","每一粒粮食都凝聚着农民的辛苦。"],"reading":"后两句由劳动现场转到餐桌，用“粒粒”强调没有一粒来得容易。","clauses":["谁知盘中餐，","粒粒皆辛苦。"]}]},"poem-5":{"title":"古朗月行（节选）","intro":"“古朗月行”是诗题；这里选的是诗人回想小时候看月亮的几句。","theme":"白玉盘、瑶台镜都是比喻，来自儿童对月亮形状和光泽的联想。诗中先是“呼作”，再是“又疑”，想象一层接一层。","glossary":[{"word":"小时","meaning":"小时候"},{"word":"不识","meaning":"不认识，不知道是什么"},{"word":"月","meaning":"月亮"},{"word":"呼作","meaning":"称作、叫作"},{"word":"白玉盘","meaning":"白玉做的圆盘，用来比喻圆月"},{"word":"又疑","meaning":"又怀疑、又猜想"},{"word":"瑶台","meaning":"传说中神仙居住的美玉楼台"},{"word":"镜","meaning":"镜子"},{"word":"飞","meaning":"想象镜子飞上天空"},{"word":"青云端","meaning":"高高的云上，端指上头"},{"word":"在","meaning":"处在某个地方"}],"lines":[{"translations":["小时候不认识月亮。","把它叫作白玉做的圆盘。"],"reading":"这是儿童凭形状作出的命名，写出了天真，而不是月亮真的变成玉盘。","clauses":["小时不识月，","呼作白玉盘。"]},{"translations":["又猜想它是神仙瑶台上的明镜。","飞到了高高的云彩上面。"],"reading":"比喻从人间器物转到仙境，月亮显得更加奇妙。","clauses":["又疑瑶台镜，","飞在青云端。"]}]},"poem-6":{"title":"风","intro":"诗中没有直接出现“风”字，而是通过风带来的变化写风。","theme":"落叶、开花、江浪、斜竹从不同季节和环境表现风的力量。“千尺”“万竿”是夸张，不是测量记录。","glossary":[{"word":"解","meaning":"能够"},{"word":"落","meaning":"使落下"},{"word":"三秋","meaning":"这里指秋季，常解释为深秋"},{"word":"叶","meaning":"树叶"},{"word":"能开","meaning":"能够使花开放"},{"word":"二月","meaning":"农历二月，指春天"},{"word":"花","meaning":"花朵"},{"word":"过江","meaning":"经过江面"},{"word":"千尺浪","meaning":"极高的波浪，千尺是夸张"},{"word":"入竹","meaning":"吹入竹林"},{"word":"万竿","meaning":"许多竹子，竿是竹子的计量词"},{"word":"斜","meaning":"倾斜、弯向一旁"}],"lines":[{"translations":["风能使秋天的树叶飘落。","也能催开早春二月的花朵。"],"reading":"“落”和“开”相对，把同一种自然力量在不同季节的作用写出来。","clauses":["解落三秋叶，","能开二月花。"]},{"translations":["风吹过江面，掀起高高的浪。","吹进竹林，使许多竹子倾斜。"],"reading":"从水的波动和竹子的摇摆来感受看不见的风，是侧面描写。","clauses":["过江千尺浪，","入竹万竿斜。"]}]},"poem-7":{"title":"春晓","intro":"“春晓”指春天的清晨；晓是天刚亮。","theme":"诗人由醒来听鸟，想到夜里的风雨，再想到落花。写的是爱春惜春的心情，结尾留给读者想象。","glossary":[{"word":"春眠","meaning":"春夜的睡眠"},{"word":"不觉","meaning":"没有察觉"},{"word":"晓","meaning":"天亮"},{"word":"处处","meaning":"各个地方"},{"word":"闻","meaning":"听见"},{"word":"啼鸟","meaning":"鸣叫的鸟"},{"word":"夜来","meaning":"昨夜"},{"word":"风雨声","meaning":"刮风下雨的声音"},{"word":"花落","meaning":"花朵被打落"},{"word":"知多少","meaning":"不知道有多少，带猜想、惋惜的意味"}],"lines":[{"translations":["春夜睡得香，不知不觉天已亮了。","到处都能听见鸟儿的鸣叫。"],"reading":"先写人的感受，再写清晨的声音，读来亲切自然。","clauses":["春眠不觉晓，","处处闻啼鸟。"]},{"translations":["想起昨夜听见的风雨声。","不知道有多少花被吹落了。"],"reading":"诗人没有亲眼写落花，而是由声音想象花的遭遇，含着惜春之情。","clauses":["夜来风雨声，","花落知多少。"]}]},"poem-8":{"title":"赠汪伦","intro":"“赠”是赠送；李白写诗送给朋友汪伦。","theme":"离别的突然惊喜与潭水的深度相连，写出真挚友情。“不及”使看得见的深水成为看不见的感情的参照。","glossary":[{"word":"乘舟","meaning":"坐船"},{"word":"将欲行","meaning":"正准备离去，将是将要，欲是想要"},{"word":"忽闻","meaning":"忽然听见"},{"word":"岸上","meaning":"水岸边"},{"word":"踏歌","meaning":"一边唱歌一边踏地打节拍"},{"word":"桃花潭","meaning":"潭的名称"},{"word":"水深千尺","meaning":"潭水很深，千尺是夸张"},{"word":"不及","meaning":"比不上"},{"word":"送我情","meaning":"送别我时表现的友情"},{"word":"李白","meaning":"诗人自称自己的姓名"},{"word":"声","meaning":"声音"},{"word":"汪伦","meaning":"前来送别李白的朋友"}],"lines":[{"translations":["李白坐上船，正准备出发。","忽然听见岸上传来踏地唱歌的声音。"],"reading":"用自己的名字入诗，像直接记下送别现场；“忽”写出意外和感动。","clauses":["李白乘舟将欲行，","忽闻岸上踏歌声。"]},{"translations":["桃花潭的水纵然深达千尺。","也比不上汪伦送别我的深厚情谊。"],"reading":"不是比较水与人的高度，而是借“深”这个共同特点表达友情深厚。","clauses":["桃花潭水深千尺，","不及汪伦送我情。"]}]},"poem-9":{"title":"静夜思","intro":"“静夜”是安静的夜晚；“思”在这里指思念故乡。","theme":"由见月光到疑为霜，再到望月思乡，写的是一瞬间自然流露的乡愁。明月连接异乡和故乡。","glossary":[{"word":"床前","meaning":"床的前面，教材通常如此理解"},{"word":"明月光","meaning":"明亮的月光"},{"word":"疑","meaning":"怀疑、以为"},{"word":"是","meaning":"就是"},{"word":"地上霜","meaning":"地面上的白霜"},{"word":"举头","meaning":"抬起头"},{"word":"望","meaning":"看、远望"},{"word":"明月","meaning":"明亮的月亮"},{"word":"低头","meaning":"低下头"},{"word":"思","meaning":"思念"},{"word":"故乡","meaning":"出生或长久生活过的家乡"}],"lines":[{"translations":["床前洒着明亮的月光。","恍惚间以为是地上结了白霜。"],"reading":"“疑”写初见月光时的错觉，月光与霜的颜色、清冷感觉相通。","clauses":["床前明月光，","疑是地上霜。"]},{"translations":["抬头望着天空的明月。","低下头，不禁思念起故乡。"],"reading":"抬头与低头两个动作，把看景到动情的变化写得简洁而清楚。","clauses":["举头望明月，","低头思故乡。"]}]},"poem-10":{"title":"寻隐者不遇","intro":"寻是寻找、拜访；隐者是隐居的人；不遇是没有遇见。","theme":"全诗用问答交代寻访经过，问句被省去，只留下童子的回答。越说越具体，却始终找不到人，表现山林幽深与隐者生活的远离尘俗。","glossary":[{"word":"松下","meaning":"松树下面"},{"word":"问","meaning":"询问"},{"word":"童子","meaning":"小孩子，这里是隐者的弟子"},{"word":"言","meaning":"说、回答"},{"word":"师","meaning":"师父"},{"word":"采药","meaning":"到山里采集药草"},{"word":"去","meaning":"离开这里去做某事"},{"word":"只在","meaning":"就在"},{"word":"此山","meaning":"这座山"},{"word":"中","meaning":"里面"},{"word":"云深","meaning":"云雾浓重、山深处"},{"word":"不知处","meaning":"不知道具体在什么地方"}],"lines":[{"translations":["我在松树下询问一个童子。","他说，师父到山里采药去了。"],"reading":"“言”后面是童子的回答；虽然没有写问题，也能推想诗人在问隐者在哪里。","clauses":["松下问童子，","言师采药去。"]},{"translations":["师父就在这座山里。","可是山深云密，不知道具体在哪儿。"],"reading":"“只在”带来希望，“不知”又让希望落空，留出悠远的想象空间。","clauses":["只在此山中，","云深不知处。"]}]},"poem-11":{"title":"池上","intro":"题目点明小池上的生活场景。","theme":"诗把小孩的淘气和天真写在一起：想偷偷采莲，却留下明显水路。语气亲切，不是严厉责备。","glossary":[{"word":"小娃","meaning":"小孩子"},{"word":"撑","meaning":"用竹篙使小船前进"},{"word":"小艇","meaning":"小船"},{"word":"偷采","meaning":"偷偷采摘"},{"word":"白莲","meaning":"白莲的莲蓬"},{"word":"回","meaning":"回来"},{"word":"不解","meaning":"不懂得，解读jiě"},{"word":"藏","meaning":"隐藏"},{"word":"踪迹","meaning":"行动留下的痕迹"},{"word":"浮萍","meaning":"浮在水面的小植物"},{"word":"一道开","meaning":"分开成一条水路"}],"lines":[{"translations":["小孩子撑着一只小船。","偷偷摘了白莲蓬回来。"],"reading":"“小”字重复，显出孩子与小船的可爱；“偷”写他不愿被人发现。","clauses":["小娃撑小艇，","偷采白莲回。"]},{"translations":["他还不懂得藏起自己的踪迹。","船把水面浮萍分开，留出了一道痕迹。"],"reading":"诗人从浮萍的变化看出秘密，细节既有画面，也有幽默感。","clauses":["不解藏踪迹，","浮萍一道开。"]}]},"poem-12":{"title":"小池","intro":"写初夏小池塘的细微景物。","theme":"泉水、树阴、荷尖、蜻蜓组成清新小景。诗人用“惜”“爱”把自然写得有情，用“才”“早”表现发现的惊喜。","glossary":[{"word":"泉眼","meaning":"泉水涌出的出口"},{"word":"无声","meaning":"没有声响"},{"word":"惜","meaning":"爱惜，拟人写法"},{"word":"细流","meaning":"细小的水流"},{"word":"树阴","meaning":"树木形成的阴影"},{"word":"照水","meaning":"倒映在水里"},{"word":"爱","meaning":"喜爱，拟人写法"},{"word":"晴柔","meaning":"晴天柔和的风光"},{"word":"小荷","meaning":"刚长出的荷叶"},{"word":"才","meaning":"刚刚"},{"word":"露","meaning":"露出"},{"word":"尖尖角","meaning":"未展开的荷叶尖端"},{"word":"早有","meaning":"已经有"},{"word":"蜻蜓","meaning":"一种会飞的昆虫"},{"word":"立上头","meaning":"停立在荷叶尖上"}],"lines":[{"translations":["泉眼静静流着水，像是舍不得让细流多流一点。","树阴映在水中，仿佛喜爱晴日的柔和风光。"],"reading":"“惜”“爱”是诗人的想象，不是泉眼和树真的具有人的心理。","clauses":["泉眼无声惜细流，","树阴照水爱晴柔。"]},{"translations":["小荷叶才刚露出尖尖的角。","就已经有一只蜻蜓停在上面了。"],"reading":"“才”与“早”相呼应，一点新生的荷尖和一只蜻蜓就让初夏鲜活起来。","clauses":["小荷才露尖尖角，","早有蜻蜓立上头。"]}]},"poem-13":{"title":"画鸡","intro":"“画鸡”可理解为描写画中的鸡；重点写雄鸡的外形与报晓。","theme":"前两句写红冠白羽，后两句写平日少鸣、鸣则惊人。通过“不开口”到“一叫”的变化，赞美雄鸡的精神。","glossary":[{"word":"红冠","meaning":"公鸡头上红色的肉冠，冠读guān"},{"word":"不用裁","meaning":"不必裁剪、装饰"},{"word":"满身","meaning":"全身"},{"word":"雪白","meaning":"像雪一样白"},{"word":"走将来","meaning":"走过来，将是语助成分"},{"word":"平生","meaning":"平时"},{"word":"轻言语","meaning":"随便开口鸣叫"},{"word":"一叫","meaning":"一旦鸣叫"},{"word":"千门万户","meaning":"很多人家"},{"word":"开","meaning":"打开门户，开始一天生活"},{"word":"头上","meaning":"头的上面"},{"word":"不敢","meaning":"不轻易、不会随便"}],"lines":[{"translations":["公鸡头上的红冠天然长成，不用裁剪。","它披着雪白的羽毛，朝这里走来。"],"reading":"红与白的颜色对比，使公鸡的外形鲜明、精神。","clauses":["头上红冠不用裁，","满身雪白走将来。"]},{"translations":["它平时不轻易开口鸣叫。","可是一叫，千家万户就开门迎接清晨。"],"reading":"把报晓写成影响千家万户的大事，末句带有夸张与赞叹。","clauses":["平生不敢轻言语，","一叫千门万户开。"]}]},"poem-14":{"title":"梅花","intro":"梅花在寒冷中开放，常被用来寄托坚韧、清雅的品格。","theme":"从墙角的少量梅枝写到远处传来的香气，不夸繁华，突出不怕严寒和自有芬芳。","glossary":[{"word":"墙角","meaning":"墙壁转角处"},{"word":"数枝","meaning":"几枝"},{"word":"凌寒","meaning":"冒着严寒，凌是冒着"},{"word":"独自","meaning":"独个儿"},{"word":"开","meaning":"开放"},{"word":"遥知","meaning":"远远就知道"},{"word":"不是雪","meaning":"不是积雪"},{"word":"为","meaning":"因为，读wèi"},{"word":"有","meaning":"具有"},{"word":"暗香","meaning":"隐隐传来的清香"},{"word":"来","meaning":"飘过来"},{"word":"梅","meaning":"梅树或梅花"}],"lines":[{"translations":["墙角有几枝梅花。","正冒着寒冷，独自开放。"],"reading":"“墙角”不显眼，“独自”不热闹，却更衬出梅花的坚强。","clauses":["墙角数枝梅，","凌寒独自开。"]},{"translations":["远远便知道那白色的不是雪。","因为有淡淡的清香飘过来。"],"reading":"“不是雪”从视觉转到嗅觉，用香气认出梅花，写法很巧。","clauses":["遥知不是雪，","为有暗香来。"]}]},"poem-15":{"title":"小儿垂钓","intro":"“垂钓”就是钓鱼；写一个孩子学钓鱼时专注又有趣的神态。","theme":"外貌、坐姿、招手都像现场观察。孩子不是不礼貌，而是怕惊走鱼，结尾点明动作原因。","glossary":[{"word":"蓬头","meaning":"头发散乱"},{"word":"稚子","meaning":"年幼的孩子"},{"word":"学","meaning":"学习"},{"word":"垂纶","meaning":"钓鱼，纶读lún，指钓鱼线"},{"word":"侧坐","meaning":"侧着身子坐"},{"word":"莓苔","meaning":"野草和苔藓"},{"word":"草映身","meaning":"草遮映着身子"},{"word":"路人","meaning":"过路的人"},{"word":"借问","meaning":"向人打听"},{"word":"遥","meaning":"远远地"},{"word":"招手","meaning":"挥动手示意"},{"word":"怕得","meaning":"生怕"},{"word":"鱼惊","meaning":"鱼儿受到惊吓"},{"word":"不应人","meaning":"不出声回答别人，应读yìng"}],"lines":[{"translations":["一个头发乱蓬蓬的小孩子正在学钓鱼。","他侧身坐在野草苔藓旁，青草掩映着身体。"],"reading":"看似随意的坐姿中藏着认真，写孩子的动作而不直接说“专心”。","clauses":["蓬头稚子学垂纶，","侧坐莓苔草映身。"]},{"translations":["路人向他问路，他远远地摆手。","因为怕惊动鱼儿，所以不出声回答。"],"reading":"“招手”在这里要联系“不应人”理解为示意，不能只理解成热情招呼。","clauses":["路人借问遥招手，","怕得鱼惊不应人。"]}]},"poem-16":{"title":"登鹳雀楼","intro":"登是登上；鹳雀楼是楼名，诗写登楼所见和继续向上的想法。","theme":"前两句天地开阔，后两句由景生理：位置更高，视野更远。它既是登楼经验，也启发人不断进取。","glossary":[{"word":"白日","meaning":"太阳"},{"word":"依山","meaning":"靠着山"},{"word":"尽","meaning":"消失在视野中"},{"word":"黄河","meaning":"河流名"},{"word":"入海流","meaning":"向大海流去"},{"word":"欲","meaning":"想要"},{"word":"穷","meaning":"尽、达到尽头"},{"word":"千里目","meaning":"望向很远的目光，千里是概数"},{"word":"更","meaning":"再"},{"word":"上","meaning":"登上"},{"word":"一层楼","meaning":"更高的一层"}],"lines":[{"translations":["太阳靠着远山渐渐落下。","黄河奔流，向大海而去。"],"reading":"一边写落日，一边写流水；“入海”包含对黄河流向的想象，并非楼上可直接望见海。","clauses":["白日依山尽，","黄河入海流。"]},{"translations":["想把远处的景物看得更尽一些。","就要再登上一层楼。"],"reading":"“穷”不是贫穷，而是穷尽；登高望远的动作自然引出道理。","clauses":["欲穷千里目，","更上一层楼。"]}]},"poem-17":{"title":"望庐山瀑布","intro":"“望”是远望；庐山是山名，香炉是其中一座峰的名字。","theme":"先写烟霞背景，再写瀑布的静态与动态，最后用银河落天的想象表现壮丽气势。","glossary":[{"word":"日照","meaning":"太阳照耀"},{"word":"香炉","meaning":"庐山香炉峰，不是屋里的香炉"},{"word":"生","meaning":"产生、升起"},{"word":"紫烟","meaning":"日光下呈紫色的山间云雾"},{"word":"遥看","meaning":"远远望去"},{"word":"瀑布","meaning":"从高处倾泻的水流"},{"word":"挂","meaning":"像悬挂着"},{"word":"前川","meaning":"山前的河流，形容瀑布像挂在山前的长河"},{"word":"飞流","meaning":"飞奔直下的水流"},{"word":"直下","meaning":"笔直落下"},{"word":"三千尺","meaning":"极高，夸张"},{"word":"疑","meaning":"仿佛、以为"},{"word":"银河","meaning":"天空中带状的星群"},{"word":"九天","meaning":"极高的天空"},{"word":"是","meaning":"就是、好像是"},{"word":"落","meaning":"从高处降下"}],"lines":[{"translations":["太阳照着香炉峰，升起紫色云雾。","远远看去，瀑布好像一条长河悬挂在山前。"],"reading":"“挂”把流动的瀑布写成远看的整体形态，显得雄伟。","clauses":["日照香炉生紫烟，","遥看瀑布挂前川。"]},{"translations":["飞奔的水流从极高处直泻而下。","仿佛天上的银河从高空落下来。"],"reading":"“三千尺”与“九天”是夸张、想象，重在气势，不能按实测高度理解。","clauses":["飞流直下三千尺，","疑是银河落九天。"]}]},"poem-18":{"title":"江雪","intro":"以雪中的江面写出极静、极冷的环境和独钓的人。","theme":"“千山”“万径”极写空寂，“孤”“独”收束到一个老人。画面既孤清，也能让人感到独自坚守的力量。","glossary":[{"word":"千山","meaning":"许多山"},{"word":"鸟飞绝","meaning":"飞鸟的踪影全无，绝是没有"},{"word":"万径","meaning":"许多小路，径是路径"},{"word":"人踪灭","meaning":"人的足迹消失，灭是没有"},{"word":"孤舟","meaning":"独单的一只小船"},{"word":"蓑笠翁","meaning":"穿蓑衣戴斗笠的老翁"},{"word":"蓑","meaning":"用草编的雨衣"},{"word":"笠","meaning":"竹编的帽子"},{"word":"独钓","meaning":"独自钓鱼"},{"word":"寒江雪","meaning":"寒冷的、飘雪的江面"}],"lines":[{"translations":["群山中见不到飞鸟。","条条小路上也没有人的踪迹。"],"reading":"不是说一共恰好一千座山、一万条路，而是用大数词强调空旷寂静。","clauses":["千山鸟飞绝，","万径人踪灭。"]},{"translations":["只有一只小船，船上坐着披蓑衣、戴斗笠的老人。","他独自在寒江风雪中垂钓。"],"reading":"由广阔背景聚焦到一个人，孤独感更强；钓的是江中鱼，不是“雪”。","clauses":["孤舟蓑笠翁，","独钓寒江雪。"]}]},"poem-19":{"title":"夜宿山寺","intro":"夜宿是夜里住宿；山寺是山上的寺院。","theme":"用伸手摘星、不敢高声的想象突出楼高。“恐惊”把心理活动写得天真又有趣。","glossary":[{"word":"危楼","meaning":"高楼，危在这里是高"},{"word":"高百尺","meaning":"非常高，带夸张"},{"word":"手可摘","meaning":"伸手好像就能摘取"},{"word":"星辰","meaning":"天上的星星"},{"word":"不敢","meaning":"不敢做"},{"word":"高声语","meaning":"大声说话"},{"word":"恐","meaning":"怕、担心"},{"word":"惊","meaning":"惊动"},{"word":"天上人","meaning":"想象中的天上仙人"}],"lines":[{"translations":["寺里的楼高高耸立。","好像伸手就能摘到星星。"],"reading":"“危”不是危险；“摘星”不是实际发生的动作，而是以想象写高。","clauses":["危楼高百尺，","手可摘星辰。"]},{"translations":["我不敢大声说话。","怕惊动住在天上的仙人。"],"reading":"不直接重复“楼很高”，而用不敢出声的心理再次表现高度。","clauses":["不敢高声语，","恐惊天上人。"]}]},"poem-20":{"title":"敕勒歌","intro":"北朝民歌，敕勒是古代北方民族名；川指平川、平原。","theme":"用帐篷比天空，展现草原的辽阔。“见牛羊”让原本静止的画面随风显露，充满生活气息。","glossary":[{"word":"敕勒川","meaning":"敕勒族生活的平原，敕读chì、勒读lè"},{"word":"阴山","meaning":"北方山脉名"},{"word":"下","meaning":"山脚下"},{"word":"天似","meaning":"天空像"},{"word":"穹庐","meaning":"圆顶毡帐，穹读qióng"},{"word":"笼盖","meaning":"笼罩、覆盖"},{"word":"四野","meaning":"四周的原野"},{"word":"苍苍","meaning":"青苍辽远的样子"},{"word":"茫茫","meaning":"辽阔无边的样子"},{"word":"风吹","meaning":"风吹过"},{"word":"草低","meaning":"草被吹得俯下"},{"word":"见","meaning":"显现，读xiàn"},{"word":"牛羊","meaning":"牧养的牛与羊"},{"word":"天","meaning":"天空"},{"word":"野","meaning":"辽阔的原野"}],"lines":[{"translations":["敕勒族生活的原野。","就在阴山脚下。"],"reading":"先点出地点，如同把一幅草原长卷展开。","clauses":["敕勒川，","阴山下，"]},{"translations":["天空好像一顶圆圆的大毡帐。","笼罩着四周的原野。"],"reading":"用牧民熟悉的帐篷作比喻，贴近草原生活。","clauses":["天似穹庐，","笼盖四野。"]},{"translations":["天空青苍辽远。","草原辽阔无边。"],"reading":"两个叠词让声音舒展，也使视野开阔。","clauses":["天苍苍，","野茫茫，"]},{"translations":["风一吹，牧草俯下，便露出了牛羊。"],"reading":"原来牛羊被茂草遮住；风带来动作，也显出草盛畜多。","clauses":["风吹草低见牛羊。"]}]},"poem-21":{"title":"村居","intro":"村居指住在乡村；这首诗写早春乡村景色和孩子放风筝。","theme":"前半写春景，后半写儿童活动。“忙趁”表现孩子珍惜春光、急切玩耍的心情。","glossary":[{"word":"草长","meaning":"草木生长，长读zhǎng"},{"word":"莺飞","meaning":"黄莺飞舞"},{"word":"二月天","meaning":"农历二月的时节"},{"word":"拂堤","meaning":"轻轻拂动堤岸"},{"word":"杨柳","meaning":"柳树"},{"word":"醉春烟","meaning":"仿佛陶醉在春日烟霭中，拟人"},{"word":"儿童","meaning":"小孩子"},{"word":"散学","meaning":"放学"},{"word":"归来","meaning":"回来"},{"word":"早","meaning":"时间还早"},{"word":"忙趁","meaning":"赶忙趁着"},{"word":"东风","meaning":"春风"},{"word":"放","meaning":"放飞"},{"word":"纸鸢","meaning":"风筝，鸢读yuān"}],"lines":[{"translations":["早春二月，草木生长，黄莺飞舞。","堤岸上的柳条轻拂，仿佛陶醉在迷蒙的春烟里。"],"reading":"“醉”赋予柳树人的感受，也写出春景柔和、令人沉醉。","clauses":["草长莺飞二月天，","拂堤杨柳醉春烟。"]},{"translations":["孩子们早早放学回家。","赶忙趁着春风放起风筝。"],"reading":"风、孩子、风筝共同构成活泼的春日生活图。","clauses":["儿童散学归来早，","忙趁东风放纸鸢。"]}]},"poem-22":{"title":"咏柳","intro":"咏是用诗歌描写、赞美；全诗赞美春柳，也赞美春天的创造力。","theme":"先把整树柳色比成碧玉，再把柳条比成丝带，最后把春风比成剪刀，从整体看到细部。","glossary":[{"word":"碧玉","meaning":"碧绿色的玉，这里比喻鲜绿柳叶"},{"word":"妆成","meaning":"装饰成"},{"word":"一树高","meaning":"满树高高的样子，一是满、全"},{"word":"万条","meaning":"许多枝条"},{"word":"垂下","meaning":"向下垂落"},{"word":"绿丝绦","meaning":"绿色丝带，绦读tāo"},{"word":"不知","meaning":"不知道，带设问"},{"word":"细叶","meaning":"细细的柳叶"},{"word":"谁","meaning":"什么人"},{"word":"裁出","meaning":"裁剪出来"},{"word":"二月","meaning":"农历二月"},{"word":"春风","meaning":"春天的风"},{"word":"似","meaning":"像"},{"word":"剪刀","meaning":"裁剪器具"}],"lines":[{"translations":["高高的柳树像是用碧玉装饰成的。","垂下的许多柳条像绿色丝带。"],"reading":"两个比喻连着写颜色与形态，使柳树像精心装扮的人。","clauses":["碧玉妆成一树高，","万条垂下绿丝绦。"]},{"translations":["不知道细细的柳叶是谁裁出来的。","原来早春二月的春风就像剪刀。"],"reading":"先问后答，不是说风真拿剪刀，而是赞美春天使万物更新。","clauses":["不知细叶谁裁出，","二月春风似剪刀。"]}]},"poem-23":{"title":"赋得古原草送别（节选）","intro":"“赋得”是依题作诗的题式；古原是古老的原野。这里只展示原诗前四句，未包含后面的送别内容。","theme":"野草由枯到荣、被烧又生，表现生命力。读节选可体会顽强，但不要误说全诗没有送别主题。","glossary":[{"word":"离离","meaning":"草茂盛的样子"},{"word":"原上","meaning":"原野上"},{"word":"草","meaning":"野草"},{"word":"一岁","meaning":"一年"},{"word":"一枯荣","meaning":"一次枯萎，一次繁荣"},{"word":"野火","meaning":"野外燃烧的火"},{"word":"烧不尽","meaning":"不能把生命完全烧绝"},{"word":"春风","meaning":"春天的风"},{"word":"吹","meaning":"吹拂"},{"word":"又生","meaning":"重新生长"}],"lines":[{"translations":["原野上的草长得十分茂盛。","每年都经历一次枯萎和一次繁荣。"],"reading":"“枯荣”写的是草的季节循环，不是每棵草只活一年。","clauses":["离离原上草，","一岁一枯荣。"]},{"translations":["野火不能把它们彻底烧尽。","春风吹来，它们又重新生长。"],"reading":"地下根系保存生机，“又”突出被打击以后仍可复苏的力量。","clauses":["野火烧不尽，","春风吹又生。"]}]},"poem-24":{"title":"晓出净慈寺送林子方","intro":"清晨走出净慈寺，送别朋友林子方；诗的主体写西湖盛夏风光。","theme":"辽阔的绿与明艳的红相互映衬。虽然题目是送别，诗句没有直写离愁，而把情意融在美景里。","glossary":[{"word":"晓出","meaning":"清晨出门"},{"word":"毕竟","meaning":"到底、终究"},{"word":"西湖","meaning":"杭州西湖"},{"word":"六月中","meaning":"农历六月的时节"},{"word":"风光","meaning":"景色"},{"word":"不与","meaning":"不同于"},{"word":"四时","meaning":"四个季节，这里指其他时节"},{"word":"同","meaning":"相同"},{"word":"接天","meaning":"连向天边"},{"word":"莲叶","meaning":"荷叶"},{"word":"无穷碧","meaning":"望不到边的碧绿"},{"word":"映日","meaning":"映着太阳"},{"word":"荷花","meaning":"莲花"},{"word":"别样红","meaning":"格外鲜红"}],"lines":[{"translations":["到底是西湖六月时的景色。","风光与其他时节大不相同。"],"reading":"先作总体赞叹，后面才具体回答哪里不同。","clauses":["毕竟西湖六月中，","风光不与四时同。"]},{"translations":["荷叶连到天边，满眼都是无边的碧绿。","阳光映照下的荷花显得格外鲜红。"],"reading":"“无穷”写范围，“别样”写颜色，绿是底色，红是亮点。","clauses":["接天莲叶无穷碧，","映日荷花别样红。"]}]},"poem-25":{"title":"绝句（两个黄鹂鸣翠柳）","intro":"“绝句”是诗体名；括号里的首句用于和其他同名作品区别。","theme":"黄绿白青色彩鲜明，鸣、上、含、泊动静交错。窗框像画框，把远山近水收在一处。","glossary":[{"word":"黄鹂","meaning":"一种羽色鲜黄的鸣禽"},{"word":"鸣","meaning":"鸣叫"},{"word":"翠柳","meaning":"翠绿的柳树"},{"word":"一行","meaning":"排成一列，行读háng"},{"word":"白鹭","meaning":"白色的水鸟"},{"word":"上青天","meaning":"飞上蓝天"},{"word":"窗含","meaning":"从窗中看去，景色仿佛被窗框含在里面"},{"word":"西岭","meaning":"成都以西的雪山"},{"word":"千秋雪","meaning":"终年不化、仿佛积存很久的雪"},{"word":"门泊","meaning":"门前停泊，泊读bó"},{"word":"东吴","meaning":"古代长江下游一带"},{"word":"万里船","meaning":"远行万里的船，夸张写航程"},{"word":"两个","meaning":"两只，个在这里作鸟的量词"}],"lines":[{"translations":["两只黄鹂在翠绿的柳树上鸣叫。","一行白鹭飞向蓝天。"],"reading":"色彩明亮，声音与飞行动作相配，写出春日生机。","clauses":["两个黄鹂鸣翠柳，","一行白鹭上青天。"]},{"translations":["从窗户望去，可以看到西岭长年积雪。","门前停着将要远航东吴的船。"],"reading":"“千秋”拉长时间，“万里”拓展空间，小屋里的视野因而十分开阔。","clauses":["窗含西岭千秋雪，","门泊东吴万里船。"]}]},"poem-26":{"title":"悯农·其一","intro":"“悯农”是体恤农民；这首着重写丰收与饥饿并存的矛盾。","theme":"一粒变万颗，土地都耕种，却仍有人挨饿。强烈反差让读者思考农民的处境，不能简单归因为他们不努力。","glossary":[{"word":"春种","meaning":"春天播种"},{"word":"一粒粟","meaning":"一粒谷子，粟读sù"},{"word":"秋收","meaning":"秋天收获"},{"word":"万颗子","meaning":"许多粮食籽粒，万是概数"},{"word":"四海","meaning":"天下、全国"},{"word":"无","meaning":"没有"},{"word":"闲田","meaning":"没有耕种的田地"},{"word":"农夫","meaning":"种田的人"},{"word":"犹","meaning":"仍然"},{"word":"饿死","meaning":"因缺少食物而死"}],"lines":[{"translations":["春天播下一粒谷子。","秋天可以收获成千上万的粮食籽粒。"],"reading":"用数量变化写丰收，为后面的转折作铺垫。","clauses":["春种一粒粟，","秋收万颗子。"]},{"translations":["天下没有闲置不种的田。","可是农民仍然有人饥饿而死。"],"reading":"“无闲田”与“犹饿死”形成尖锐对照，表现同情与质问。","clauses":["四海无闲田，","农夫犹饿死。"]}]},"poem-27":{"title":"舟夜书所见","intro":"“舟夜”是在船上的夜晚；“书”是写下，不是书本。","theme":"从黑夜里一点渔灯写到波中满河灯影，抓住微风使水面变化的一瞬。小景也能有丰富层次。","glossary":[{"word":"月黑","meaning":"没有月光或月色昏暗"},{"word":"见","meaning":"看见"},{"word":"渔灯","meaning":"渔船上的灯"},{"word":"孤光","meaning":"孤单的一点灯光"},{"word":"一点萤","meaning":"像一只萤火虫的亮点"},{"word":"微微","meaning":"轻轻地"},{"word":"风簇浪","meaning":"风吹得波浪聚起、涌动，簇读cù"},{"word":"散作","meaning":"散开变成"},{"word":"满河星","meaning":"像满河的星光，实际是灯光在波中的倒影"}],"lines":[{"translations":["月色昏暗的夜里，看见一盏渔灯。","孤单的灯光像一只小小的萤火虫。"],"reading":"灯并非真的变小，黑暗中的远景使它显得像一点微光。","clauses":["月黑见渔灯，","孤光一点萤。"]},{"translations":["微风轻轻吹起细浪。","一点灯影便散成满河闪烁的星光。"],"reading":"“一点”到“满河”来自倒影被波纹分开，写出了光与水的互动。","clauses":["微微风簇浪，","散作满河星。"]}]},"poem-28":{"title":"所见","intro":"题目是“所看见的”，写诗人在乡间看见牧童的一刻。","theme":"由响亮歌声转为突然安静，用动作变化写出儿童想捕蝉时的机灵和专注。","glossary":[{"word":"牧童","meaning":"放牛的孩子"},{"word":"骑","meaning":"跨坐在牛背上"},{"word":"黄牛","meaning":"一种家牛"},{"word":"歌声","meaning":"唱歌的声音"},{"word":"振","meaning":"振荡、回响"},{"word":"林樾","meaning":"树木成阴的地方，樾读yuè"},{"word":"意欲","meaning":"心里想要"},{"word":"捕","meaning":"捉"},{"word":"鸣蝉","meaning":"正在叫的蝉"},{"word":"忽然","meaning":"一下子"},{"word":"闭口","meaning":"停止唱歌"},{"word":"立","meaning":"站定不动"}],"lines":[{"translations":["牧童骑在黄牛背上。","歌声在浓密的树林间回荡。"],"reading":"先写移动与歌唱，展示孩子自在的心情。","clauses":["牧童骑黄牛，","歌声振林樾。"]},{"translations":["他忽然想捕捉正在鸣叫的蝉。","便立刻闭上嘴，站定不动。"],"reading":"“闭口立”不是无缘无故停下，而是怕惊动蝉，心理藏在动作中。","clauses":["意欲捕鸣蝉，","忽然闭口立。"]}]},"poem-29":{"title":"山行","intro":"写在深秋山中行走时看见的景物。","theme":"石径、白云、人家引出枫林，最后赞霜叶胜春花。全诗没有一味悲秋，而是欣赏秋色的鲜艳与生命力。","glossary":[{"word":"远上","meaning":"向远处高处延伸"},{"word":"寒山","meaning":"深秋时的山"},{"word":"石径","meaning":"石铺的小路"},{"word":"斜","meaning":"斜伸、曲折延伸"},{"word":"白云生处","meaning":"白云升起、缭绕的地方"},{"word":"人家","meaning":"住户"},{"word":"停车","meaning":"停下车"},{"word":"坐","meaning":"因为"},{"word":"爱","meaning":"喜爱"},{"word":"枫林晚","meaning":"傍晚的枫树林"},{"word":"霜叶","meaning":"经霜变红的叶子"},{"word":"红于","meaning":"比……更红"},{"word":"二月花","meaning":"早春的花"},{"word":"有","meaning":"存在、可以看见"}],"lines":[{"translations":["石头小路斜斜伸向深秋的远山。","白云升起、缭绕的地方，还有几户人家。"],"reading":"视线沿着小路向上，把深山写得有层次，也有人间气息。","clauses":["远上寒山石径斜，","白云生处有人家。"]},{"translations":["停下车来，是因为喜爱傍晚的枫林。","经霜的枫叶，比二月的春花还要红。"],"reading":"“坐”不能译成坐下；“于”表示比较，末句突出秋色胜过春花。","clauses":["停车坐爱枫林晚，","霜叶红于二月花。"]}]},"poem-30":{"title":"赠刘景文","intro":"赠给友人刘景文的诗，借秋末冬初的景色勉励朋友。","theme":"荷尽菊残并不意味着全无好景，成熟的橙橘仍可欣赏。由衰败写到丰美，表达珍惜当下、不轻言衰老的鼓励。","glossary":[{"word":"荷尽","meaning":"荷花凋谢、荷叶枯败"},{"word":"擎雨盖","meaning":"像伞一样托住雨水的荷叶，擎是举、托"},{"word":"菊残","meaning":"菊花凋残"},{"word":"犹有","meaning":"仍有"},{"word":"傲霜枝","meaning":"不惧寒霜的枝干"},{"word":"一年","meaning":"一整年"},{"word":"好景","meaning":"美好的景色"},{"word":"君","meaning":"你，指刘景文"},{"word":"须记","meaning":"一定记住"},{"word":"最是","meaning":"最值得珍惜的是"},{"word":"橙黄橘绿时","meaning":"橙子金黄、橘子青绿的秋末冬初时节"},{"word":"已无","meaning":"已经没有"}],"lines":[{"translations":["荷花凋谢了，连挡雨的荷叶也没有了。","菊花虽残，却还留着不怕寒霜的枝条。"],"reading":"“已无”和“犹有”形成变化，残景中仍然能看到坚韧。","clauses":["荷尽已无擎雨盖，","菊残犹有傲霜枝。"]},{"translations":["一年中的美好景色，你一定要记住。","尤其是橙黄橘绿的这个时节。"],"reading":"诗意转向成熟与收获；给朋友的劝勉含在景物中。","clauses":["一年好景君须记，","最是橙黄橘绿时。"]}]},"poem-31":{"title":"夜书所见","intro":"“书”是写下，记下秋夜所见所感。","theme":"先写秋风引动乡愁，再写夜灯下的儿童活动。眼前异乡的小灯，容易让人想起故乡生活。","glossary":[{"word":"萧萧","meaning":"风吹草木的声音"},{"word":"梧叶","meaning":"梧桐树叶"},{"word":"送寒声","meaning":"送来带着寒意的声响"},{"word":"江上","meaning":"江边"},{"word":"秋风","meaning":"秋天的风"},{"word":"动","meaning":"触动、引起"},{"word":"客情","meaning":"旅居外地的思乡之情"},{"word":"知有","meaning":"料想有"},{"word":"挑促织","meaning":"用细枝逗引、捉蟋蟀，挑读tiǎo"},{"word":"促织","meaning":"蟋蟀"},{"word":"夜深","meaning":"夜已很晚"},{"word":"篱落","meaning":"篱笆"},{"word":"一灯明","meaning":"一盏灯亮着"},{"word":"儿童","meaning":"小孩子"}],"lines":[{"translations":["风吹梧桐叶，萧萧声中带来寒意。","江上的秋风触动了旅人的思乡之情。"],"reading":"“寒”既是秋夜体感，也衬托心中孤寂。","clauses":["萧萧梧叶送寒声，","江上秋风动客情。"]},{"translations":["料想是孩子们正在逗捉蟋蟀。","因为深夜的篱笆旁，还亮着一盏灯。"],"reading":"前一句是由灯光作出的推想，不必理解成诗人清楚看见每个孩子。","clauses":["知有儿童挑促织，","夜深篱落一灯明。"]}]},"poem-32":{"title":"望天门山","intro":"天门山是夹江对峙的山；楚江在这里指流经此地的长江。","theme":"江水冲开山势、青山迎面展开、孤帆从日边而来，表现江山的雄奇和行船时视角的变化。","glossary":[{"word":"天门","meaning":"天门山"},{"word":"中断","meaning":"从中间断开"},{"word":"楚江","meaning":"长江流经古楚地的一段"},{"word":"开","meaning":"冲开"},{"word":"碧水","meaning":"碧绿的江水"},{"word":"东流","meaning":"向东流"},{"word":"至此","meaning":"到这里"},{"word":"回","meaning":"回旋、转向"},{"word":"两岸","meaning":"江水两边"},{"word":"青山","meaning":"青绿色的山"},{"word":"相对出","meaning":"对立的山峰似迎面显现"},{"word":"孤帆","meaning":"一片孤单的船帆，代指船"},{"word":"日边","meaning":"太阳所在方向的天边"},{"word":"来","meaning":"驶来"},{"word":"一片","meaning":"一面船帆，突出远看时的小小形状"}],"lines":[{"translations":["天门山仿佛被长江从中间冲开。","碧绿的江水东流，到这里回旋奔涌。"],"reading":"“开”写出水势强大，“回”写出山势对水流的影响。","clauses":["天门中断楚江开，","碧水东流至此回。"]},{"translations":["两岸的青山相对着，仿佛迎面展开。","一只孤帆从太阳所在的远方驶来。"],"reading":"“出”让山有动态感，与观察者行进时景物显现的过程有关。","clauses":["两岸青山相对出，","孤帆一片日边来。"]}]},"poem-33":{"title":"饮湖上初晴后雨","intro":"饮是饮酒；湖指杭州西湖；写先晴后雨时的湖光山色。","theme":"晴有晴的明丽，雨有雨的朦胧。把西湖比作西施，说明不同状态各有美，而非只赞一种天气。","glossary":[{"word":"水光","meaning":"水面反射的光"},{"word":"潋滟","meaning":"水波荡漾、波光闪动，读liàn yàn"},{"word":"晴方好","meaning":"晴天正显得美好"},{"word":"山色","meaning":"山的景象"},{"word":"空蒙","meaning":"云雾迷茫"},{"word":"雨亦奇","meaning":"雨中也很奇妙"},{"word":"欲","meaning":"想要"},{"word":"把","meaning":"将"},{"word":"西湖","meaning":"杭州西湖"},{"word":"西子","meaning":"西施，古代美女"},{"word":"淡妆","meaning":"淡雅的妆饰"},{"word":"浓抹","meaning":"浓艳的妆饰"},{"word":"总相宜","meaning":"总是合适、都很好看"},{"word":"比","meaning":"比作、作比喻"}],"lines":[{"translations":["晴天的湖面波光闪动，景色正好。","雨中的山色朦胧，也别有奇妙之处。"],"reading":"“方好”和“亦奇”并列肯定，晴雨都值得欣赏。","clauses":["水光潋滟晴方好，","山色空蒙雨亦奇。"]},{"translations":["若把西湖比作美人西施。","无论淡妆还是浓妆，都十分相宜。"],"reading":"以人的美说明湖的美，淡妆浓抹对应不同景态，不必硬分唯一对应关系。","clauses":["欲把西湖比西子，","淡妆浓抹总相宜。"]}]},"poem-34":{"title":"望洞庭","intro":"远望秋夜的洞庭湖，湖中的君山是画面焦点。","theme":"月光和湖水柔和相融，再以银盘、青螺作比，写出宁静玲珑之美。","glossary":[{"word":"湖光","meaning":"湖面的光"},{"word":"秋月","meaning":"秋夜月光"},{"word":"两相和","meaning":"两者协调融合，和读hé"},{"word":"潭面","meaning":"湖面"},{"word":"无风","meaning":"没有风"},{"word":"镜未磨","meaning":"像尚未磨亮的铜镜"},{"word":"遥望","meaning":"远远望去"},{"word":"洞庭","meaning":"洞庭湖"},{"word":"山水翠","meaning":"山水显出青绿色"},{"word":"白银盘","meaning":"比喻月光下的湖面"},{"word":"一青螺","meaning":"一只青色螺壳，比喻湖中君山"},{"word":"里","meaning":"里面"}],"lines":[{"translations":["湖光与秋月的光色彼此融合。","无风的湖面，像一面还没有磨亮的铜镜。"],"reading":"古铜镜未磨时光色柔暗，这一比喻写柔和、迷蒙，不是现代玻璃镜。","clauses":["湖光秋月两相和，","潭面无风镜未磨。"]},{"translations":["远望洞庭湖的青山绿水。","好像白银盘里放着一只青色的小螺。"],"reading":"银盘是湖，青螺是山，比例一大一小，画面十分精巧。","clauses":["遥望洞庭山水翠，","白银盘里一青螺。"]}]},"poem-35":{"title":"早发白帝城","intro":"早发是早晨出发；白帝城在今重庆奉节一带，江陵在今湖北。","theme":"极快的舟行与轻快的语气相应。“千里”“万重”写路远山多，反衬一天即到的畅快。","glossary":[{"word":"朝辞","meaning":"早晨告别，朝读zhāo"},{"word":"白帝","meaning":"白帝城"},{"word":"彩云间","meaning":"绚丽朝霞环绕的高处"},{"word":"千里","meaning":"形容路途遥远"},{"word":"江陵","meaning":"地名"},{"word":"一日还","meaning":"一天便到，还读huán，指返回"},{"word":"两岸","meaning":"江的两边"},{"word":"猿声","meaning":"猿的叫声"},{"word":"啼不住","meaning":"叫个不停"},{"word":"轻舟","meaning":"轻快的小船"},{"word":"已过","meaning":"已经越过"},{"word":"万重山","meaning":"重重叠叠的群山，重读chóng"}],"lines":[{"translations":["清晨告别彩云环绕的白帝城。","远在千里之外的江陵，一天便可以回到。"],"reading":"早晨与一日、彩云与千里，写出了行程快、心境开朗。","clauses":["朝辞白帝彩云间，","千里江陵一日还。"]},{"translations":["两岸的猿声还在不断传来。","轻快的小船已经越过重重山峦。"],"reading":"声音似乎还未过去，船已越过山，借听觉经验表现速度。","clauses":["两岸猿声啼不住，","轻舟已过万重山。"]}]},"poem-36":{"title":"采莲曲","intro":"写江南采莲女子与荷花荷叶相映的画面。","theme":"绿裙与荷叶、脸庞与荷花互相映衬。先看不清人，再从歌声发现人，有色彩，也有声音。","glossary":[{"word":"荷叶","meaning":"莲的叶子"},{"word":"罗裙","meaning":"用丝织品制成的裙子"},{"word":"一色裁","meaning":"仿佛用同一种颜色的材料裁成"},{"word":"芙蓉","meaning":"荷花"},{"word":"向脸","meaning":"朝着采莲人的脸"},{"word":"两边开","meaning":"在脸旁两侧开放"},{"word":"乱入","meaning":"交杂混入"},{"word":"池中","meaning":"荷花池里"},{"word":"看不见","meaning":"难以分辨人影"},{"word":"闻歌","meaning":"听见歌声"},{"word":"始觉","meaning":"才知道、才察觉"},{"word":"有人来","meaning":"有采莲人来到这里"}],"lines":[{"translations":["采莲人的绿裙与荷叶像用同一颜色裁成。","荷花在她们的脸庞两边开放。"],"reading":"不是说荷叶真的做裙子，而是写人和景颜色相融。","clauses":["荷叶罗裙一色裁，","芙蓉向脸两边开。"]},{"translations":["人影混入荷花池中，难以看清。","听见歌声，才知道有人采莲而来。"],"reading":"视觉暂时失灵，听觉补上，使藏在花叶中的生活显得鲜活。","clauses":["乱入池中看不见，","闻歌始觉有人来。"]}]},"poem-37":{"title":"绝句（迟日江山丽）","intro":"写春日江山与燕子、鸳鸯的活动。","theme":"前两句总写明丽与芳香，后两句以飞燕、睡鸟分别表现忙碌与安适，构成温暖和谐的春景。","glossary":[{"word":"迟日","meaning":"春天白昼渐长，不是太阳迟到"},{"word":"江山","meaning":"江河山野"},{"word":"丽","meaning":"美丽"},{"word":"春风","meaning":"春天的风"},{"word":"花草香","meaning":"花草散发香气"},{"word":"泥融","meaning":"泥土湿润、松软"},{"word":"飞燕子","meaning":"燕子飞来飞去，衔泥筑巢"},{"word":"沙暖","meaning":"沙地被阳光晒暖"},{"word":"睡鸳鸯","meaning":"鸳鸯在沙上安睡"},{"word":"鸳鸯","meaning":"常成对活动的水鸟"}],"lines":[{"translations":["春日里江山格外秀丽。","春风送来花草的香气。"],"reading":"视觉与嗅觉相连，让春天既看得见，又仿佛闻得到。","clauses":["迟日江山丽，","春风花草香。"]},{"translations":["泥土温软，燕子忙着飞来衔泥。","沙地暖和，鸳鸯安静地睡着。"],"reading":"一动一静分别照应“泥融”“沙暖”，动物的状态表现春暖。","clauses":["泥融飞燕子，","沙暖睡鸳鸯。"]}]},"poem-38":{"title":"惠崇春江晚景","intro":"惠崇是善画的僧人；这是诗人题写在画作上的诗。","theme":"诗不仅描绘画里的竹桃鸭子，还补入水温和河豚将至的想象，说明题画诗可以写画外之意。","glossary":[{"word":"竹外","meaning":"竹林外"},{"word":"桃花","meaning":"桃树的花"},{"word":"三两枝","meaning":"几枝"},{"word":"春江","meaning":"春天的江水"},{"word":"水暖","meaning":"江水回暖"},{"word":"鸭先知","meaning":"鸭子在水中，先感到水温变化"},{"word":"蒌蒿","meaning":"水边的一种草，读lóu hāo"},{"word":"满地","meaning":"遍地"},{"word":"芦芽","meaning":"芦苇的嫩芽"},{"word":"短","meaning":"刚生出不久"},{"word":"正是","meaning":"恰好是"},{"word":"河豚","meaning":"一种鱼，豚读tún"},{"word":"欲上时","meaning":"将要逆水游来的时节"}],"lines":[{"translations":["竹林外有几枝桃花开放。","春江的水回暖，在水中活动的鸭子先感受到。"],"reading":"“先知”由鸭的活动联想到水温，不是宣布只有鸭能知道春天。","clauses":["竹外桃花三两枝，","春江水暖鸭先知。"]},{"translations":["蒌蒿遍地，芦苇的嫩芽还短。","这正是河豚将要逆水游来的时节。"],"reading":"从植物萌发生长推知季节，再想到画面之外的鱼，丰富了春意。","clauses":["蒌蒿满地芦芽短，","正是河豚欲上时。"]}]},"poem-39":{"title":"三衢道中","intro":"三衢是地名，在今浙江衢州一带；道中指旅途中。","theme":"写初夏晴日山行，景色清新。来路与返程比较，绿阴没减，黄鹂又添声，表现意外的好心情。","glossary":[{"word":"梅子黄时","meaning":"梅子成熟发黄的初夏时节"},{"word":"日日晴","meaning":"接连晴天"},{"word":"小溪","meaning":"溪流"},{"word":"泛尽","meaning":"乘小船走到水路尽头，泛指行舟"},{"word":"却","meaning":"再、又"},{"word":"山行","meaning":"沿山路行走"},{"word":"绿阴","meaning":"树木的浓荫"},{"word":"不减","meaning":"并不少"},{"word":"来时路","meaning":"来程所走的路"},{"word":"添得","meaning":"又增加"},{"word":"黄鹂","meaning":"鸟名"},{"word":"四五声","meaning":"几声清脆鸣叫"}],"lines":[{"translations":["梅子黄熟的时节，天天晴朗。","乘船走完小溪，又改走山路。"],"reading":"“却”在此不是转折的“却”，而是再、又，表示行程衔接。","clauses":["梅子黄时日日晴，","小溪泛尽却山行。"]},{"translations":["沿路绿阴不比来时少。","还新添了几声黄鹂的鸣叫。"],"reading":"“不减”“添得”由视觉转向听觉，惊喜层层加深。","clauses":["绿阴不减来时路，","添得黄鹂四五声。"]}]},"poem-40":{"title":"忆江南","intro":"“忆江南”是词牌名；这首词写对江南春景的怀念。","theme":"红花比火，绿水如蓝，色彩对照强烈。开头直赞“好”，结尾反问，首尾都包含深厚记忆。","glossary":[{"word":"江南","meaning":"长江以南地区"},{"word":"好","meaning":"美好"},{"word":"风景","meaning":"景色"},{"word":"旧曾","meaning":"从前曾经"},{"word":"谙","meaning":"熟悉，读ān"},{"word":"日出","meaning":"太阳升起"},{"word":"江花","meaning":"江边的花"},{"word":"红胜火","meaning":"红得胜过火焰"},{"word":"春来","meaning":"春天到来"},{"word":"江水","meaning":"江中的水"},{"word":"绿如蓝","meaning":"像蓝草染出的青绿颜色，蓝指可制染料的植物"},{"word":"能不","meaning":"怎么能不"},{"word":"忆","meaning":"怀念"}],"lines":[{"translations":["江南真美好。","那里的风景，我从前就很熟悉。"],"reading":"“谙”表示亲身熟悉，说明后面的赞美来自生活记忆。","clauses":["江南好，","风景旧曾谙。"]},{"translations":["日出时，江边的花红得胜过火焰。","春天到来，江水绿得像蓝草染出的颜色。"],"reading":"“蓝”不是把江水说成现代色名的蓝色，而与古代染料植物有关。","clauses":["日出江花红胜火，","春来江水绿如蓝。"]},{"translations":["怎么能够不怀念江南呢？"],"reading":"反问实际是在肯定：这样的江南让人难忘。","clauses":["能不忆江南？"]}]},"poem-41":{"title":"元日","intro":"元日指农历正月初一，写新年到来的热闹与更新。","theme":"爆竹、饮酒、日出、换桃符串起节日习俗，表现迎新喜悦，也可体会除旧布新的愿望。","glossary":[{"word":"爆竹","meaning":"古时燃竹或后来燃放的爆竹"},{"word":"一岁除","meaning":"旧的一年过去，除是消逝"},{"word":"春风","meaning":"带来春意的风"},{"word":"送暖","meaning":"送来暖意"},{"word":"屠苏","meaning":"屠苏酒，古时新年饮用的一种酒"},{"word":"千门万户","meaning":"许多人家"},{"word":"曈曈日","meaning":"初升太阳明亮的样子，曈读tóng"},{"word":"总把","meaning":"都把"},{"word":"新桃","meaning":"新的桃符"},{"word":"旧符","meaning":"旧桃符"},{"word":"桃符","meaning":"古时悬挂门旁、用来祈福辟邪的桃木板"},{"word":"声中","meaning":"声音之中"},{"word":"入","meaning":"进入、融入"},{"word":"换","meaning":"更换"}],"lines":[{"translations":["爆竹声中，旧的一年过去。","春风送来暖意，人们迎新饮着屠苏酒。"],"reading":"声音、气候与习俗相配，营造出新年气氛。","clauses":["爆竹声中一岁除，","春风送暖入屠苏。"]},{"translations":["初升的太阳照亮千家万户。","家家都把旧桃符换成新桃符。"],"reading":"“新桃”不是新鲜桃子；换桃符表现辞旧迎新。","clauses":["千门万户曈曈日，","总把新桃换旧符。"]}]},"poem-42":{"title":"清明","intro":"清明是节气，也与扫墓等习俗相关；诗写行旅者雨中的愁绪。","theme":"从绵绵春雨到问路求酒，再到远处村庄，情景逐渐转向可寻的慰藉；没有明说行人正在扫墓。","glossary":[{"word":"清明时节","meaning":"清明节气前后"},{"word":"雨纷纷","meaning":"雨细密、接连不断"},{"word":"路上","meaning":"途中"},{"word":"行人","meaning":"行路的人"},{"word":"欲断魂","meaning":"仿佛失魂落魄，形容愁苦"},{"word":"借问","meaning":"请问"},{"word":"酒家","meaning":"卖酒的店"},{"word":"何处有","meaning":"哪里有"},{"word":"牧童","meaning":"放牧的孩子"},{"word":"遥指","meaning":"指向远处"},{"word":"杏花村","meaning":"杏花掩映的村庄，具体地望有不同说法"}],"lines":[{"translations":["清明时节，细雨接连不断地下着。","路上的行人满心愁苦，像要失魂落魄。"],"reading":"雨与愁相互衬托，“断魂”是夸张的情绪描写。","clauses":["清明时节雨纷纷，","路上行人欲断魂。"]},{"translations":["请问，哪里有可以歇脚饮酒的店？","牧童伸手指向远处杏花掩映的村庄。"],"reading":"一句问话、一个手势，不写回答原话也能交代方向。","clauses":["借问酒家何处有？","牧童遥指杏花村。"]}]},"poem-43":{"title":"九月九日忆山东兄弟","intro":"九月九日是重阳节；“山东”指华山以东的故乡一带，不能直接当作今天的山东省。","theme":"先直写独在异乡的思亲，再转到想象亲人也想念自己。由对方落笔，使孤独更深。","glossary":[{"word":"独","meaning":"独自"},{"word":"异乡","meaning":"外地"},{"word":"异客","meaning":"身在他乡的客人"},{"word":"每逢","meaning":"每当遇到"},{"word":"佳节","meaning":"美好的节日，这里指重阳"},{"word":"倍","meaning":"更加"},{"word":"思亲","meaning":"思念亲人"},{"word":"遥知","meaning":"在远处想象、料知"},{"word":"兄弟","meaning":"兄弟亲人"},{"word":"登高","meaning":"重阳登临高处的习俗"},{"word":"遍插","meaning":"人人插戴"},{"word":"茱萸","meaning":"一种芳香植物，读zhū yú"},{"word":"少一人","meaning":"少了远行的诗人自己"},{"word":"在","meaning":"身处"},{"word":"为","meaning":"成为、做，读wéi"},{"word":"处","meaning":"地方"}],"lines":[{"translations":["独自住在他乡，做着异地的客人。","每到节日，就加倍思念亲人。"],"reading":"“独”“异”重复强调与故乡相隔；欢乐节日反而使孤独更明显。","clauses":["独在异乡为异客，","每逢佳节倍思亲。"]},{"translations":["遥想兄弟们正在登高。","他们都插戴着茱萸，只少了我一个人。"],"reading":"诗人没有亲眼见到，是想象故乡的情形，含蓄地写双方的牵挂。","clauses":["遥知兄弟登高处，","遍插茱萸少一人。"]}]},"poem-44":{"title":"滁州西涧","intro":"滁州是地名；西涧是城西的溪涧。","theme":"幽草、鸟鸣、急雨春潮、空渡孤舟，静与动相衬。诗中的自横之舟带来安静、自在而略显寂寥的感受。","glossary":[{"word":"独怜","meaning":"特别喜爱，怜是爱"},{"word":"幽草","meaning":"幽静处的小草"},{"word":"涧边","meaning":"山间水沟旁"},{"word":"上有","meaning":"上方有"},{"word":"黄鹂","meaning":"鸟名"},{"word":"深树","meaning":"枝叶浓密的树"},{"word":"鸣","meaning":"鸣叫"},{"word":"春潮","meaning":"春天上涨的水"},{"word":"带雨","meaning":"夹着雨"},{"word":"晚来急","meaning":"傍晚来得急"},{"word":"野渡","meaning":"郊野渡口"},{"word":"无人","meaning":"没有人"},{"word":"舟自横","meaning":"船自行横在那里，横是横浮着"},{"word":"生","meaning":"生长"}],"lines":[{"translations":["我特别喜爱涧边幽静的小草。","上方茂密的树丛里，黄鹂在鸣叫。"],"reading":"视线由草移到树，鸟鸣反衬环境的幽静。","clauses":["独怜幽草涧边生，","上有黄鹂深树鸣。"]},{"translations":["春潮夹着雨，傍晚时来得更急。","郊野渡口没有人，只有一只船横在水面。"],"reading":"“急”的水势与“自横”的船相对，动静之间见出野趣。","clauses":["春潮带雨晚来急，","野渡无人舟自横。"]}]},"poem-45":{"title":"大林寺桃花","intro":"写春末来到山寺，意外遇见盛放桃花。","theme":"山上山下花期不同，本是自然现象，诗人却想象春天躲进山寺，由惜春变成寻春的惊喜。","glossary":[{"word":"人间","meaning":"这里指山下平地"},{"word":"四月","meaning":"农历四月"},{"word":"芳菲尽","meaning":"春花凋谢，芳菲指花草、花香"},{"word":"山寺","meaning":"山中的寺院"},{"word":"桃花","meaning":"桃树的花"},{"word":"始","meaning":"才、刚刚"},{"word":"盛开","meaning":"繁盛开放"},{"word":"长恨","meaning":"常常惋惜"},{"word":"春归","meaning":"春天离去"},{"word":"无觅处","meaning":"没有地方寻找，觅是找"},{"word":"不知","meaning":"没想到"},{"word":"转入","meaning":"转移到了"},{"word":"此中","meaning":"这山寺里"},{"word":"来","meaning":"来到这里"}],"lines":[{"translations":["四月里，山下的春花已经凋谢。","山寺的桃花却才刚刚盛开。"],"reading":"“尽”与“始”形成反差，高处较凉使花期较晚。","clauses":["人间四月芳菲尽，","山寺桃花始盛开。"]},{"translations":["我常常惋惜春天离去，无处找寻。","却没想到它转到了这座山寺之中。"],"reading":"把春天写成会躲藏、会搬家的人，表达意外重逢的喜悦。","clauses":["长恨春归无觅处，","不知转入此中来。"]}]},"poem-46":{"title":"鹿柴","intro":"鹿柴是王维辋川别业的一处地名；“柴”读zhài，指栅栏、围寨。","theme":"诗用人语反衬山静，以夕照衬出林深。不是山上绝对无人，而是看不见人，只闻其声。","glossary":[{"word":"空山","meaning":"空旷幽静的山"},{"word":"不见人","meaning":"看不见人的身影"},{"word":"但","meaning":"只"},{"word":"闻","meaning":"听见"},{"word":"人语响","meaning":"人说话的声音"},{"word":"返景","meaning":"夕阳返照的光，景指日光，其读音注法有差异，随所用课本"},{"word":"入","meaning":"照进"},{"word":"深林","meaning":"幽深的树林"},{"word":"复","meaning":"又"},{"word":"照","meaning":"照射"},{"word":"青苔","meaning":"贴地生长的绿色苔藓"},{"word":"上","meaning":"上面"}],"lines":[{"translations":["幽静的山里看不见人。","只听见有人说话的声音。"],"reading":"声音显出空间的空旷，并没有破坏整体宁静，属于以声衬静。","clauses":["空山不见人，","但闻人语响。"]},{"translations":["夕阳返照的光照进深林。","又映在地上的青苔上。"],"reading":"光只照亮局部，反而让周围的幽深更明显；返景不是树的黑影。","clauses":["返景入深林，","复照青苔上。"]}]},"poem-47":{"title":"暮江吟","intro":"暮是傍晚；吟是吟咏；写从日落到夜晚的江边景色。","theme":"江面两色与露月相映，是诗人细看光色的结果。“可怜”在古诗中常是可爱、值得喜爱。","glossary":[{"word":"一道","meaning":"一片、一抹"},{"word":"残阳","meaning":"将落的夕阳"},{"word":"铺","meaning":"平铺着，形容低斜阳光照水"},{"word":"水中","meaning":"水面上"},{"word":"半江","meaning":"一半江面"},{"word":"瑟瑟","meaning":"这里形容碧绿色"},{"word":"红","meaning":"夕照映出的红色"},{"word":"可怜","meaning":"可爱"},{"word":"九月初三","meaning":"农历九月初三"},{"word":"夜","meaning":"夜晚"},{"word":"露","meaning":"露珠"},{"word":"真珠","meaning":"珍珠"},{"word":"似","meaning":"像"},{"word":"弓","meaning":"弯弓，借形容初月"},{"word":"月","meaning":"新月，农历月初弯弯的月亮"}],"lines":[{"translations":["一抹夕阳铺在江面上。","一半江水碧绿，一半江水映成红色。"],"reading":"“铺”写太阳贴近地平线时，光斜斜照在水上的样子。","clauses":["一道残阳铺水中，","半江瑟瑟半江红。"]},{"translations":["多么可爱的九月初三夜晚。","露珠像珍珠，弯月像一张弓。"],"reading":"初三月细弯；诗从开阔江面转向微小露珠与天上初月。","clauses":["可怜九月初三夜，","露似真珠月似弓。"]}]},"poem-48":{"title":"题西林壁","intro":"题是在墙壁上题写；西林指庐山西林寺。","theme":"从不同位置看山，形状各不相同。后两句由此说明观察事物受位置与眼界限制，应从多方面了解。","glossary":[{"word":"横看","meaning":"从正面看"},{"word":"岭","meaning":"连绵山岭"},{"word":"侧","meaning":"从侧面看"},{"word":"峰","meaning":"高耸山峰"},{"word":"远近高低","meaning":"远处近处、高处低处等不同角度"},{"word":"各不同","meaning":"各有不同"},{"word":"不识","meaning":"不能认清"},{"word":"庐山","meaning":"山名"},{"word":"真面目","meaning":"真实、完整的样貌"},{"word":"只缘","meaning":"只因为"},{"word":"身在","meaning":"自己处在"},{"word":"此山中","meaning":"这座山里面"},{"word":"成","meaning":"呈现为、显出……的样子"}],"lines":[{"translations":["从正面看是连绵山岭，从侧面看又成了山峰。","从远近高低的各处看去，样子都不同。"],"reading":"同一庐山没有变，变的是观察者的位置和看到的局部。","clauses":["横看成岭侧成峰，","远近高低各不同。"]},{"translations":["不能认清庐山完整的面貌。","正因为自己就在这座山中。"],"reading":"说明局部视角会有限制，不等于说身在其中就什么也不能认识。","clauses":["不识庐山真面目，","只缘身在此山中。"]}]},"poem-49":{"title":"雪梅","intro":"把梅与雪写成争春的双方，通过评比写出各自长处。","theme":"雪白、梅香，优势不同，不能只用一条标准判高低。诗有趣味，也有认识事物的启发。","glossary":[{"word":"争春","meaning":"争着显示春的美"},{"word":"未肯降","meaning":"谁也不肯认输，降读xiáng"},{"word":"骚人","meaning":"诗人"},{"word":"搁笔","meaning":"放下笔"},{"word":"费评章","meaning":"难以评判，评章是评议"},{"word":"须","meaning":"应当"},{"word":"逊","meaning":"比不上"},{"word":"三分白","meaning":"白的程度略逊，三分非精确计量"},{"word":"却","meaning":"但是"},{"word":"输","meaning":"不及"},{"word":"一段香","meaning":"一番清香"},{"word":"梅雪","meaning":"梅花和雪"},{"word":"梅","meaning":"梅花"},{"word":"雪","meaning":"白雪"}],"lines":[{"translations":["梅花和雪都争着报春，谁也不肯服输。","诗人放下笔，觉得难以评出高低。"],"reading":"让花雪像人一样比赛，开篇便富有情趣。","clauses":["梅雪争春未肯降，","骚人搁笔费评章。"]},{"translations":["论洁白，梅花比雪略逊一些。","论清香，雪却比不上梅花。"],"reading":"两句对照，分别选取颜色、香气，结论是各有所长。","clauses":["梅须逊雪三分白，","雪却输梅一段香。"]}]},"poem-50":{"title":"嫦娥","intro":"借嫦娥奔月的神话写清冷孤独的感受；诗意可以有不同理解，不宜认定单一人物。","theme":"前两句由室内烛影到将晓星河，显出长夜难眠。后两句以“应”推想嫦娥心情，并不是神话事实记录。","glossary":[{"word":"云母屏风","meaning":"嵌有云母装饰的屏风"},{"word":"烛影深","meaning":"烛光映照深暗、渐弱"},{"word":"长河","meaning":"银河"},{"word":"渐落","meaning":"慢慢向西下沉"},{"word":"晓星","meaning":"拂晓的星星"},{"word":"沉","meaning":"隐没"},{"word":"嫦娥","meaning":"神话中奔月的人物"},{"word":"应","meaning":"想来应当"},{"word":"悔","meaning":"后悔"},{"word":"偷灵药","meaning":"神话中私自服下长生药"},{"word":"碧海青天","meaning":"广阔清冷的天地"},{"word":"夜夜心","meaning":"夜夜孤寂的心情"}],"lines":[{"translations":["云母屏风上，烛影深深。","银河渐渐西落，晨星也将隐去。"],"reading":"景物随夜色变动，暗示人已经独自度过漫长一夜。","clauses":["云母屏风烛影深，","长河渐落晓星沉。"]},{"translations":["想来嫦娥也会后悔服下灵药。","面对碧海青天，每夜都怀着孤独的心情。"],"reading":"“应悔”是诗人的想象与寄托，不是对神话人物的确定判断。","clauses":["嫦娥应悔偷灵药，","碧海青天夜夜心。"]}]},"poem-51":{"title":"出塞","intro":"“出塞”是乐府旧题，写边关战争与守边愿望。","theme":"明月、关塞连接古今，照见长期征战。诗盼有良将守土，让将士免受无休止的远征。","glossary":[{"word":"秦时明月汉时关","meaning":"秦汉以来的明月与边关，是互文，不专分月属秦、关属汉"},{"word":"万里","meaning":"遥远路途"},{"word":"长征","meaning":"长途征战，不是现代长征"},{"word":"人未还","meaning":"征人尚未归来"},{"word":"但使","meaning":"只要"},{"word":"龙城飞将","meaning":"善守边的名将，常联系李广理解，具体所指有争议"},{"word":"在","meaning":"在世、在此守卫"},{"word":"不教","meaning":"不让"},{"word":"胡马","meaning":"古诗中对北方来犯骑兵的称呼"},{"word":"度","meaning":"越过"},{"word":"阴山","meaning":"北方山脉名"}],"lines":[{"translations":["还是秦汉以来的明月，还是古老的边关。","远行万里去征战的人，却仍没有回来。"],"reading":"“秦”“汉”共同写时间久远，表达边患与征战绵延不断。","clauses":["秦时明月汉时关，","万里长征人未还。"]},{"translations":["只要有英勇善战的名将镇守。","就不让来犯骑兵越过阴山。"],"reading":"写的是守卫边疆的期望，同时含着对久征不归者的关切。","clauses":["但使龙城飞将在，","不教胡马度阴山。"]}]},"poem-52":{"title":"凉州词（葡萄美酒夜光杯）","intro":"凉州词是曲调名；这首写边地将士宴饮与面对战争的心声。","theme":"华美酒宴与残酷战场相对。既有豪放，也藏着伤感，不能只读作鼓励饮酒或单纯好战。","glossary":[{"word":"葡萄美酒","meaning":"葡萄酿的美酒"},{"word":"夜光杯","meaning":"精美酒杯"},{"word":"欲饮","meaning":"正要饮酒"},{"word":"琵琶","meaning":"弹拨乐器"},{"word":"马上催","meaning":"马上奏出的琵琶声催促饮酒或出征，理解有不同"},{"word":"醉卧","meaning":"喝醉后躺卧"},{"word":"沙场","meaning":"战场"},{"word":"君","meaning":"你"},{"word":"莫笑","meaning":"不要笑"},{"word":"古来","meaning":"自古以来"},{"word":"征战","meaning":"出征作战"},{"word":"几人回","meaning":"能有多少人回来，反问写战争残酷"}],"lines":[{"translations":["葡萄美酒盛在精美酒杯中。","正要举杯时，马上传来琵琶的催促声。"],"reading":"乐声使宴饮画面有动感，喜悦中已含急迫之感。","clauses":["葡萄美酒夜光杯，","欲饮琵琶马上催。"]},{"translations":["若我醉倒在战场上，请不要笑。","自古出征作战的人，又有多少能平安归来？"],"reading":"反问揭出生命危险，豪语背后也有沉重。","clauses":["醉卧沙场君莫笑，","古来征战几人回？"]}]},"poem-53":{"title":"夏日绝句","intro":"借楚汉历史中的项羽表达对气节的重视。","theme":"开头直抒价值判断，结尾举项羽不肯过江的故事。学习其精神寄托，也应区分诗人赞颂与完整历史评价。","glossary":[{"word":"生","meaning":"活着"},{"word":"当","meaning":"应当"},{"word":"人杰","meaning":"人中的杰出人物"},{"word":"死","meaning":"死去"},{"word":"亦","meaning":"也"},{"word":"鬼雄","meaning":"鬼中的英雄，是形象化赞语"},{"word":"至今","meaning":"直到现在"},{"word":"思","meaning":"怀念"},{"word":"项羽","meaning":"秦末起义军领袖、西楚霸王"},{"word":"不肯","meaning":"不愿"},{"word":"过江东","meaning":"渡过乌江回到江东"},{"word":"作","meaning":"做、成为"},{"word":"为","meaning":"成为、做，读wéi"}],"lines":[{"translations":["活着应当做人中的杰出人物。","死去也应当有英雄气概。"],"reading":"“生”“死”“人”“鬼”两两相对，语气坚定，表达重视气节的态度。","clauses":["生当作人杰，","死亦为鬼雄。"]},{"translations":["直到现在，人们还怀念项羽。","因为他失败后不肯渡江回江东。"],"reading":"用历史人物说明前两句的主张；重在表达面对国难时不失气节的主张。","clauses":["至今思项羽，","不肯过江东。"]}]},"poem-54":{"title":"别董大","intro":"别是送别；董大一般指音乐家董庭兰。","theme":"苍茫风雪开场，却以有力劝慰收尾。诗不止悲伤离别，还给朋友前行的信心。","glossary":[{"word":"千里","meaning":"广阔辽远"},{"word":"黄云","meaning":"昏黄的云"},{"word":"白日曛","meaning":"太阳昏暗，曛读xūn"},{"word":"北风","meaning":"寒冷北风"},{"word":"吹雁","meaning":"吹送飞雁"},{"word":"雪纷纷","meaning":"大雪接连飘落"},{"word":"莫愁","meaning":"不要忧愁"},{"word":"前路","meaning":"前面的行程"},{"word":"无知己","meaning":"没有懂得、赏识你的人"},{"word":"天下","meaning":"各地"},{"word":"谁人","meaning":"什么人"},{"word":"不识君","meaning":"不认识你，君指董大"}],"lines":[{"translations":["广阔天边黄云密布，太阳也暗淡了。","北风吹着飞雁，大雪纷纷落下。"],"reading":"寒冷苍茫的环境衬出离别处境，并为后面的温暖鼓励蓄势。","clauses":["千里黄云白日曛，","北风吹雁雪纷纷。"]},{"translations":["不要担心前路没有知己。","天下有谁不知道你的才华呢？"],"reading":"“谁人不识”是反问与赞美，重点是安慰朋友，不必按实际知名度理解。","clauses":["莫愁前路无知己，","天下谁人不识君？"]}]},"poem-55":{"title":"四时田园杂兴·其二十五","intro":"四时是一年四季；杂兴是随兴写下的诗；这一首写初夏乡村。","theme":"以果实、花色点明农时，路上无人暗示农事繁忙，蜻蜓蝴蝶的飞动衬托村庄的安静。","glossary":[{"word":"梅子金黄","meaning":"梅子已经黄熟"},{"word":"杏子肥","meaning":"杏子果实饱满"},{"word":"麦花雪白","meaning":"麦花白得像雪"},{"word":"菜花稀","meaning":"油菜花已经稀少"},{"word":"日长","meaning":"夏日白昼长"},{"word":"篱落","meaning":"篱笆"},{"word":"无人过","meaning":"没有人经过"},{"word":"惟有","meaning":"只有"},{"word":"蜻蜓","meaning":"昆虫名"},{"word":"蛱蝶","meaning":"蝴蝶，蛱读jiá"},{"word":"飞","meaning":"飞舞"}],"lines":[{"translations":["梅子已经金黄，杏子长得饱满。","麦花白得如雪，油菜花已经稀疏。"],"reading":"从不同植物的生长状态判断初夏，不是所有春花同时盛开。","clauses":["梅子金黄杏子肥，","麦花雪白菜花稀。"]},{"translations":["白昼渐长，篱笆边少有人经过。","只有蜻蜓与蝴蝶飞来飞去。"],"reading":"“无人”写眼前小路，并非村里没有居民；飞虫使静景富有生气。","clauses":["日长篱落无人过，","惟有蜻蜓蛱蝶飞。"]}]},"poem-56":{"title":"宿新市徐公店","intro":"宿是投宿；徐公店是姓徐的人开的客店。","theme":"由稀疏篱笆与长路写到孩子追蝶，黄蝶飞入黄花后难找，情节自然有趣。","glossary":[{"word":"篱落","meaning":"篱笆"},{"word":"疏疏","meaning":"稀疏的样子"},{"word":"一径深","meaning":"一条小路向远处伸去"},{"word":"树头","meaning":"树枝上"},{"word":"新绿","meaning":"新长出的绿叶"},{"word":"未成阴","meaning":"还未形成浓荫"},{"word":"儿童","meaning":"小孩子"},{"word":"急走","meaning":"快速奔跑，走在古代可表示跑"},{"word":"追","meaning":"追赶"},{"word":"黄蝶","meaning":"黄色的蝴蝶"},{"word":"飞入","meaning":"飞进"},{"word":"菜花","meaning":"油菜花"},{"word":"无处寻","meaning":"找不到了"}],"lines":[{"translations":["稀疏的篱笆旁，一条小路通向深处。","树上的新叶还未长成浓浓的绿荫。"],"reading":"先布置清新疏朗的环境，让后面的活动有了空间。","clauses":["篱落疏疏一径深，","树头新绿未成阴。"]},{"translations":["孩子飞快奔跑，追赶黄色蝴蝶。","蝴蝶飞进油菜花中，便找不到了。"],"reading":"黄蝶与黄花颜色接近；“无处寻”把孩子的失望与趣味留给读者。","clauses":["儿童急走追黄蝶，","飞入菜花无处寻。"]}]},"poem-57":{"title":"清平乐·村居","intro":"清平乐是词牌，乐读yuè；村居是题目，写乡村家庭生活。","theme":"上片写住所与老夫妇，下片写三个孩子。劳动与嬉戏并存，平常生活中有温暖安宁。","glossary":[{"word":"茅檐","meaning":"茅草屋的屋檐"},{"word":"低小","meaning":"低矮、狭小"},{"word":"溪上","meaning":"溪边"},{"word":"青青","meaning":"鲜绿的样子"},{"word":"醉里","meaning":"略带醉意"},{"word":"吴音","meaning":"吴地方言"},{"word":"相媚好","meaning":"彼此亲热说话，媚好是相互逗趣、亲昵"},{"word":"白发","meaning":"头发已白"},{"word":"翁媪","meaning":"老翁老妇，媪读ǎo"},{"word":"大儿","meaning":"大儿子"},{"word":"锄豆","meaning":"给豆田锄草"},{"word":"溪东","meaning":"溪的东边"},{"word":"中儿","meaning":"二儿子"},{"word":"织鸡笼","meaning":"编织鸡笼"},{"word":"最喜","meaning":"最惹人喜爱"},{"word":"小儿","meaning":"小儿子"},{"word":"亡赖","meaning":"同“无赖”，这里指顽皮可爱，亡读wú"},{"word":"溪头","meaning":"溪边"},{"word":"卧","meaning":"躺着"},{"word":"剥","meaning":"剥开，读bāo"},{"word":"莲蓬","meaning":"长有莲子的花托"},{"word":"草","meaning":"小草"},{"word":"谁家","meaning":"谁的一家，语气亲切"},{"word":"正","meaning":"正在"}],"lines":[{"translations":["茅草屋的屋檐低低小小。","小溪边长满了青青的草。"],"reading":"房屋虽简朴，环境却清新，先写乡居的底色。","clauses":["茅檐低小，","溪上青青草。"]},{"translations":["吴地方言在微醺中听来亲热悦耳。","那满头白发的老夫妇，是谁家的人呢？"],"reading":"“相媚好”不是讨好权贵，而是家人之间亲昵交谈。","clauses":["醉里吴音相媚好，","白发谁家翁媪？"]},{"translations":["大儿子在溪东豆田锄草。","二儿子正编织鸡笼。"],"reading":"写两个较大的孩子各做劳动，家庭生活井井有条。","clauses":["大儿锄豆溪东，","中儿正织鸡笼。"]},{"translations":["最惹人喜欢的是顽皮的小儿子。","他躺在溪边，剥着莲蓬。"],"reading":"“亡赖”是爱怜语，不是责骂；“卧”显出小孩子的自在。","clauses":["最喜小儿亡赖，","溪头卧剥莲蓬。"]}]},"poem-58":{"title":"江畔独步寻花·其五","intro":"江畔是江边；独步是独自散步；这是组诗中的第五首。","theme":"春光使人慵懒，桃花又使人流连。结尾不作定论，以深红浅红都可爱的迟疑表现赏花的兴味。","glossary":[{"word":"黄师塔","meaning":"一座塔的名称"},{"word":"江水东","meaning":"江水向东流"},{"word":"春光","meaning":"春日风光"},{"word":"懒困","meaning":"慵懒困倦"},{"word":"倚","meaning":"依靠、迎着"},{"word":"微风","meaning":"轻柔的风"},{"word":"一簇","meaning":"一丛、一团"},{"word":"开无主","meaning":"自由开放，仿佛没有主人"},{"word":"可爱","meaning":"可喜爱，句中带询问意味"},{"word":"深红","meaning":"颜色较浓的红"},{"word":"浅红","meaning":"颜色较淡的红"},{"word":"前","meaning":"前面"},{"word":"桃花","meaning":"桃树开的花"},{"word":"爱","meaning":"喜爱，这里含选择的意味"}],"lines":[{"translations":["黄师塔前的江水向东流。","和暖春光让人有些慵懒困倦，我迎着微风站着。"],"reading":"温暖春日里的感受使诗人显得悠闲，接着注意力被桃花吸引。","clauses":["黄师塔前江水东，","春光懒困倚微风。"]},{"translations":["一簇桃花自在地开放着。","究竟爱深红的呢，还是爱浅红的呢？"],"reading":"结尾像自言自语，写出花色都好、难以取舍的喜爱。","clauses":["桃花一簇开无主，","可爱深红爱浅红？"]}]},"poem-59":{"title":"蜂","intro":"咏蜂的诗，从蜜蜂采蜜引出对辛劳与享受之间关系的追问。","theme":"表面赞蜂勤劳，结尾却追问劳动成果归谁，含着对劳动者处境的思考。","glossary":[{"word":"不论","meaning":"无论"},{"word":"平地","meaning":"平坦的地方"},{"word":"与","meaning":"和"},{"word":"山尖","meaning":"山顶"},{"word":"无限风光","meaning":"到处美好的花景"},{"word":"尽被占","meaning":"都被蜜蜂占有、飞遍"},{"word":"采得","meaning":"采集到"},{"word":"百花","meaning":"许多花的花蜜"},{"word":"成蜜","meaning":"酿成蜂蜜"},{"word":"后","meaning":"以后"},{"word":"为谁","meaning":"为了谁"},{"word":"辛苦","meaning":"辛勤劳作"},{"word":"甜","meaning":"这里指让人享受蜂蜜的甘甜"}],"lines":[{"translations":["无论是在平地还是山顶。","美好的花间风光，蜜蜂都飞遍了。"],"reading":"先写蜜蜂活动广、采花勤，为后面写酿蜜铺垫。","clauses":["不论平地与山尖，","无限风光尽被占。"]},{"translations":["采集百花花蜜，酿成蜂蜜以后。","到底为谁辛苦，又让谁享受甜美呢？"],"reading":"问题没有直接回答，却让读者注意劳动与成果分配。","clauses":["采得百花成蜜后，","为谁辛苦为谁甜？"]}]},"poem-60":{"title":"独坐敬亭山","intro":"独自坐着看敬亭山；敬亭山在今安徽宣城。","theme":"鸟尽、云去，使人独处；最后把山写成懂得自己的伴侣，在孤独中获得精神慰藉。","glossary":[{"word":"众鸟","meaning":"许多鸟"},{"word":"高飞尽","meaning":"飞得高而远，直到看不见"},{"word":"孤云","meaning":"一片孤单的云"},{"word":"独去","meaning":"独自飘走"},{"word":"闲","meaning":"悠闲地"},{"word":"相看","meaning":"彼此看着"},{"word":"两","meaning":"诗人与山双方"},{"word":"不厌","meaning":"看不够、不厌倦"},{"word":"只有","meaning":"唯有"},{"word":"敬亭山","meaning":"山名"}],"lines":[{"translations":["鸟儿高飞，渐渐都看不见了。","一片孤云，也悠闲地独自飘走。"],"reading":"景物相继离开，使“独坐”的处境更鲜明。","clauses":["众鸟高飞尽，","孤云独去闲。"]},{"translations":["彼此看着，总也看不厌。","这样的伴侣，只有敬亭山了。"],"reading":"把山人格化，既写孤独，也写人与自然之间的亲近。","clauses":["相看两不厌，","只有敬亭山。"]}]},"poem-61":{"title":"芙蓉楼送辛渐","intro":"芙蓉楼是送别地点，辛渐是友人。","theme":"寒雨、孤山烘托离别，冰心玉壶则表达心地纯洁。重点不仅是朋友分别，更是请友人传达自己的品格与心意。","glossary":[{"word":"寒雨","meaning":"带寒意的雨"},{"word":"连江","meaning":"与江面连成一片"},{"word":"夜入吴","meaning":"夜里来到吴地"},{"word":"平明","meaning":"天亮时"},{"word":"送客","meaning":"送别辛渐"},{"word":"楚山孤","meaning":"远方楚地的山显得孤单"},{"word":"洛阳","meaning":"地名，亲友所在"},{"word":"亲友","meaning":"亲人朋友"},{"word":"如","meaning":"如果"},{"word":"相问","meaning":"问起我"},{"word":"一片冰心","meaning":"像冰一样纯净的心"},{"word":"玉壶","meaning":"玉制壶，比喻清洁高雅的品格"},{"word":"在","meaning":"处在、存于"}],"lines":[{"translations":["带寒意的雨连着江面，夜里我来到吴地。","天亮送你离去时，楚地山峦也显得孤单。"],"reading":"环境中的寒与孤，让送别气氛更深。","clauses":["寒雨连江夜入吴，","平明送客楚山孤。"]},{"translations":["洛阳的亲友如果问起我。","请告诉他们，我仍保持冰心玉壶般的纯洁。"],"reading":"“冰心”不是心冷无情，而是比喻内心清白、坚守操守。","clauses":["洛阳亲友如相问，","一片冰心在玉壶。"]}]},"poem-62":{"title":"塞下曲","intro":"乐府旧题，这一首写雪夜追击敌军的场景。","theme":"敌军暗夜逃走，将士准备追击，大雪落满武器。全诗省略战斗结果，把力量凝聚在出发的一刻。","glossary":[{"word":"月黑","meaning":"没有月光、夜色昏暗"},{"word":"雁飞高","meaning":"大雁高飞"},{"word":"单于","meaning":"古代匈奴首领称号，读chán yú，此处代敌军首领"},{"word":"夜遁逃","meaning":"趁夜逃走"},{"word":"欲","meaning":"正准备"},{"word":"将","meaning":"带领"},{"word":"轻骑","meaning":"装备轻便、行动迅速的骑兵，骑读qí"},{"word":"逐","meaning":"追赶"},{"word":"大雪","meaning":"纷飞大雪"},{"word":"满","meaning":"落满"},{"word":"弓刀","meaning":"弓与刀，代表将士武器"}],"lines":[{"translations":["昏暗的夜里，大雁飞得很高。","敌军首领趁着夜色逃跑。"],"reading":"雁的飞动与敌军夜逃组成紧张的边地画面。","clauses":["月黑雁飞高，","单于夜遁逃。"]},{"translations":["将军正要率领轻骑兵追赶。","大雪已经落满了弓和刀。"],"reading":"“满”写环境严寒，也衬出将士不畏艰苦的气势。","clauses":["欲将轻骑逐，","大雪满弓刀。"]}]},"poem-63":{"title":"墨梅","intro":"墨梅是用水墨画出的梅花；这是借画梅表明志趣的题画诗。","theme":"淡墨之花不争艳色，只留清气，把审美追求与做人品格联系起来。","glossary":[{"word":"洗砚池","meaning":"洗砚台的水池，常与王羲之故事相联系"},{"word":"池头","meaning":"池边"},{"word":"洗砚池头","meaning":"洗砚池边，头在这里表示旁边"},{"word":"树","meaning":"这里指梅树"},{"word":"朵朵","meaning":"每一朵"},{"word":"淡墨痕","meaning":"浅淡墨色形成的花痕"},{"word":"不要","meaning":"不求"},{"word":"人夸","meaning":"别人夸奖"},{"word":"好颜色","meaning":"鲜艳漂亮的颜色"},{"word":"只留","meaning":"只希望留下"},{"word":"清气","meaning":"梅的清香，也比喻清正品格"},{"word":"满","meaning":"充满"},{"word":"乾坤","meaning":"天地，读qián kūn"},{"word":"我家","meaning":"诗人所说的自家"},{"word":"花开","meaning":"花朵开放"}],"lines":[{"translations":["我家洗砚池边的梅树。","一朵朵花，都带着淡淡的墨色。"],"reading":"“洗砚”“墨痕”扣住绘画，不能把墨梅当成自然界黑色花种。","clauses":["我家洗砚池头树，","朵朵花开淡墨痕。"]},{"translations":["不求别人夸赞花色好看。","只愿清香与清正之气充满天地。"],"reading":"从梅花的香气转到人的操守，是托物言志。","clauses":["不要人夸好颜色，","只留清气满乾坤。"]}]},"poem-64":{"title":"卜算子·咏梅","intro":"卜算子是词牌，咏梅是题目。正文请结合课本阅读；以下按全词的先后层次讲解，不补录正文。","theme":"以严寒中的梅花表现坚强、自信与谦逊。花开不是争名，而是报春；当百花盛放，梅花也因共同的春天而喜悦。","glossary":[{"word":"卜算子","meaning":"词牌名，卜读bǔ"},{"word":"咏","meaning":"歌咏、赞美"},{"word":"梅","meaning":"梅花，词中借它寄托品格"},{"word":"俏","meaning":"美好、精神焕发"},{"word":"报春","meaning":"传递春天将来的消息"},{"word":"烂漫","meaning":"花开鲜艳繁盛的样子"}],"lines":[{"translations":["风雨把一个春天送走。","飞雪又伴随新春将至而来。"],"reading":"把风雨和飞雪写成送迎季节的使者，形成时间流转的开端。","label":"第1层意思"},{"translations":["山崖上结着厚厚的冰，环境十分严寒。","梅花却仍精神饱满地开放。"],"reading":"严寒与花开形成对照，借环境艰难突出梅花的坚韧。","label":"第2层意思"},{"translations":["梅花的美不在于与别的花争先。","它的开放像在告诉人们，春天快到了。"],"reading":"由外在形象转入精神品格，解释“美”不只是颜色好看。","label":"第3层意思"},{"translations":["等到山野里百花盛开。","梅花也融入春日花丛，为共同的繁盛而欢喜。"],"reading":"结尾用拟人表达喜悦，突出不独占春光的胸怀。","label":"第4层意思"}]},"poem-65":{"title":"蝉","intro":"借蝉的形态、声音寄托对高洁品格的推重。","theme":"表面写蝉居高声远，深层赞美自身品格与才能的重要。“饮清露”是古人对蝉的文学认识，现实中蝉主要吸取植物汁液。","glossary":[{"word":"垂緌","meaning":"下垂的帽缨，这里比蝉头部下垂的触须，緌读ruí"},{"word":"饮","meaning":"喝"},{"word":"清露","meaning":"清洁露水，诗中象征清高"},{"word":"流响","meaning":"接连传出的鸣声"},{"word":"出","meaning":"从……传出"},{"word":"疏桐","meaning":"枝叶疏朗的梧桐"},{"word":"居高","meaning":"处在高处，也寓品格高洁"},{"word":"声自远","meaning":"声音自然传得远"},{"word":"非是","meaning":"并不是"},{"word":"藉","meaning":"凭借，读jiè"},{"word":"秋风","meaning":"秋天的风"}],"lines":[{"translations":["蝉的触须像帽缨下垂，仿佛饮着清露。","连续的鸣声从疏朗梧桐间传出。"],"reading":"形象、环境和声音共同营造清雅气质；不要把文学意象当作蝉的食性说明。","clauses":["垂緌饮清露，","流响出疏桐。"]},{"translations":["因为居处高，声音自然传得远。","并不是借助秋风才如此。"],"reading":"借物讲理，强调声名应有内在根据，不只靠外力吹送。","clauses":["居高声自远，","非是藉秋风。"]}]},"poem-66":{"title":"乞巧","intro":"乞巧是七夕习俗，向织女祈求灵巧技艺。","theme":"天上相会的传说与人间穿针活动相连，写出节日热闹和人们对美好生活的愿望。","glossary":[{"word":"七夕","meaning":"农历七月初七夜"},{"word":"今宵","meaning":"今夜，宵是夜晚"},{"word":"碧霄","meaning":"碧蓝天空，霄读xiāo"},{"word":"牵牛","meaning":"牵牛星，传说中的牛郎"},{"word":"织女","meaning":"织女星及传说人物"},{"word":"渡河桥","meaning":"经过银河上的鹊桥"},{"word":"家家","meaning":"每户人家"},{"word":"乞巧","meaning":"祈求灵巧"},{"word":"望","meaning":"仰望"},{"word":"秋月","meaning":"初秋的月亮"},{"word":"穿尽","meaning":"穿过许多"},{"word":"红丝","meaning":"穿针用的红色丝线"},{"word":"几万条","meaning":"极多，夸张"},{"word":"看","meaning":"观看、仰望"}],"lines":[{"translations":["七夕夜，人们仰望碧蓝的天空。","想象牛郎织女渡过银河上的鹊桥相会。"],"reading":"把星空与传说联系起来，表现节日的文化想象。","clauses":["七夕今宵看碧霄，","牵牛织女渡河桥。"]},{"translations":["家家对着秋月祈求灵巧。","穿过的红丝线多得数也数不清。"],"reading":"末句夸张写参与者多、活动热闹，不是实际统计。","clauses":["家家乞巧望秋月，","穿尽红丝几万条。"]}]},"poem-67":{"title":"示儿","intro":"“示儿”是给儿子们看，常理解为诗人的临终嘱托。","theme":"生死将尽时最挂念的仍是国家统一。嘱咐儿孙在家祭时告知好消息，表达深切愿望。","glossary":[{"word":"死去","meaning":"死后"},{"word":"元知","meaning":"本来就知道，元同原"},{"word":"万事空","meaning":"人死后世事都与自己无关"},{"word":"但悲","meaning":"只是悲伤"},{"word":"不见","meaning":"不能亲眼看到"},{"word":"九州同","meaning":"国家统一，九州代指中国"},{"word":"王师","meaning":"宋朝的军队"},{"word":"北定","meaning":"向北收复、平定"},{"word":"中原","meaning":"黄河中下游一带"},{"word":"日","meaning":"那一天"},{"word":"家祭","meaning":"家中祭祀祖先"},{"word":"无忘","meaning":"不要忘记"},{"word":"告","meaning":"告诉"},{"word":"乃翁","meaning":"你们的父亲"}],"lines":[{"translations":["我本来知道，人死后万事都空了。","只是遗憾，没能看见国家重新统一。"],"reading":"“但”指出唯一放不下的事，使爱国情怀格外集中。","clauses":["死去元知万事空，","但悲不见九州同。"]},{"translations":["将来朝廷军队收复中原的那一天。","家祭的时候，不要忘记告诉你们的父亲。"],"reading":"以未来的家事寄托国家愿望，语气朴素而感情深重。","clauses":["王师北定中原日，","家祭无忘告乃翁。"]}]},"poem-68":{"title":"题临安邸","intro":"临安是南宋都城，今杭州；邸是旅店、住所。","theme":"层层楼阁与不断歌舞显出繁华，却反衬偏安享乐、忘记失地的危险。杭州与汴州的对照是讽刺核心。","glossary":[{"word":"山外青山","meaning":"青山之外还有青山"},{"word":"楼外楼","meaning":"楼阁层层相接"},{"word":"西湖","meaning":"杭州西湖"},{"word":"歌舞","meaning":"唱歌跳舞，指享乐生活"},{"word":"几时休","meaning":"什么时候停止"},{"word":"暖风","meaning":"温暖的风，也暗含享乐风气"},{"word":"熏","meaning":"吹拂得使人迷醉"},{"word":"游人","meaning":"游赏享乐的人"},{"word":"醉","meaning":"陶醉、沉迷"},{"word":"直把","meaning":"简直把"},{"word":"杭州","meaning":"南宋临安所在地"},{"word":"作","meaning":"当作"},{"word":"汴州","meaning":"北宋旧都汴京，今开封"},{"word":"得","meaning":"放在动词后，引出造成的结果，如熏得人醉"}],"lines":[{"translations":["青山外还有青山，楼阁外还有楼阁。","西湖边的歌舞，到底什么时候才能停下？"],"reading":"看似美景，紧接着的追问却转出批评，语气带愤慨。","clauses":["山外青山楼外楼，","西湖歌舞几时休？"]},{"translations":["温暖的风吹得享乐的人沉醉。","他们简直把杭州当成了故都汴州。"],"reading":"“醉”不只是酒醉，更指忘却国事、沉迷安逸。","clauses":["暖风熏得游人醉，","直把杭州作汴州。"]}]},"poem-69":{"title":"己亥杂诗","intro":"己亥是干支纪年；这是龚自珍组诗中的一首，呼吁打破沉闷、重视人才。","theme":"以风雷和万马齐喑对照社会生气与沉寂，最后用向天公劝告的奇想表达改革愿望。","glossary":[{"word":"九州","meaning":"中国"},{"word":"生气","meaning":"生机、活力，不是发怒"},{"word":"恃","meaning":"依靠，读shì"},{"word":"风雷","meaning":"风与雷，比喻激发社会活力的力量"},{"word":"万马齐喑","meaning":"群马都不出声，比喻普遍沉默，喑读yīn"},{"word":"究","meaning":"终究、实在"},{"word":"可哀","meaning":"令人悲哀"},{"word":"劝","meaning":"劝告"},{"word":"天公","meaning":"上天的拟人称呼"},{"word":"重抖擞","meaning":"重新振奋精神，擞读sǒu"},{"word":"不拘一格","meaning":"不局限一种规格、方式"},{"word":"降人才","meaning":"使人才涌现，降读jiàng"},{"word":"我","meaning":"诗人自称"}],"lines":[{"translations":["国家要有生机，需要风雷般的激发。","大家都沉默不言的局面，实在令人悲哀。"],"reading":"风雷是比喻，万马也不是写真实马群；两种形象写社会状态。","clauses":["九州生气恃风雷，","万马齐喑究可哀。"]},{"translations":["我劝上天重新振作精神。","不局限一种标准，让各样的人才涌现。"],"reading":"用大胆想象提出人才观，重点在打破拘束与激发生机。","clauses":["我劝天公重抖擞，","不拘一格降人才。"]}]},"poem-70":{"title":"山居秋暝","intro":"山居是山中住处；秋暝是秋日傍晚。","theme":"雨后山景、月泉声色与浣女渔舟相融，清幽而不冷清。结尾表达愿意留居的心意。","glossary":[{"word":"空山","meaning":"清幽的山林"},{"word":"新雨","meaning":"刚下过的雨"},{"word":"晚来秋","meaning":"傍晚有了秋凉"},{"word":"松间","meaning":"松树之间"},{"word":"照","meaning":"照耀"},{"word":"清泉","meaning":"清澈泉水"},{"word":"石上","meaning":"石头上"},{"word":"流","meaning":"流动"},{"word":"竹喧","meaning":"竹林传来喧笑"},{"word":"归浣女","meaning":"洗衣女子归来，浣读huàn"},{"word":"莲动","meaning":"莲叶摇动"},{"word":"下渔舟","meaning":"渔船顺流而下"},{"word":"随意","meaning":"任凭"},{"word":"春芳歇","meaning":"春日芳花消歇"},{"word":"王孙","meaning":"原指贵族子弟，这里借指诗人自己"},{"word":"自可留","meaning":"自然可以留下"},{"word":"后","meaning":"以后"},{"word":"天气","meaning":"天气状况"},{"word":"明月","meaning":"明亮的月亮"}],"lines":[{"translations":["清幽山林刚下过一场雨。","傍晚的天气带来了秋凉。"],"reading":"“空”重在清幽，不是山里无人，后面就有生活场景。","clauses":["空山新雨后，","天气晚来秋。"]},{"translations":["明月照在松树之间。","清泉从石头上流过。"],"reading":"月光偏静，泉流偏动，视觉与听觉交融。","clauses":["明月松间照，","清泉石上流。"]},{"translations":["竹林喧笑，是洗衣女子回来了。","莲叶摇动，是渔舟顺流而下。"],"reading":"先写声音、动静，再点出人和船，增加发现的趣味。","clauses":["竹喧归浣女，","莲动下渔舟。"]},{"translations":["任凭春天的花草消歇。","这样的秋山，我自可留下。"],"reading":"反用留客意象，说明秋天同样可爱，不必只恋春景。","clauses":["随意春芳歇，","王孙自可留。"]}]},"poem-71":{"title":"枫桥夜泊","intro":"夜泊是夜里停船；枫桥在今苏州。","theme":"月落、乌啼、霜气、渔火、钟声交织，表现旅人夜里的愁绪。“到”写钟声传来，扩大夜景空间。","glossary":[{"word":"月落","meaning":"月亮落下"},{"word":"乌啼","meaning":"乌鸦鸣叫"},{"word":"霜满天","meaning":"寒霜之气弥漫的感受，不是霜悬在空中"},{"word":"江枫","meaning":"江边枫树"},{"word":"渔火","meaning":"渔船灯火"},{"word":"对愁眠","meaning":"面对景物，带着愁绪难以安睡"},{"word":"姑苏","meaning":"苏州古称"},{"word":"城外","meaning":"城的外面"},{"word":"寒山寺","meaning":"寺名"},{"word":"夜半","meaning":"半夜"},{"word":"钟声","meaning":"寺院钟声"},{"word":"到","meaning":"传到"},{"word":"客船","meaning":"旅人乘坐的船"}],"lines":[{"translations":["月亮西落，乌鸦鸣叫，满天仿佛都是寒气。","我面对江边枫树和渔火，怀着愁绪难以入眠。"],"reading":"一连串声色与寒意，围绕着一个“愁”字组织起来。","clauses":["月落乌啼霜满天，","江枫渔火对愁眠。"]},{"translations":["姑苏城外的寒山寺。","半夜的钟声传到了旅人的船上。"],"reading":"钟声从远处进入近处，把孤舟与夜色联系起来。","clauses":["姑苏城外寒山寺，","夜半钟声到客船。"]}]},"poem-72":{"title":"长相思","intro":"长相思是词牌；写随行途中对故乡的思念。","theme":"上片用路程与营灯写身在远方，下片用风雪写梦难成。“身”向外走，“心”却留故园。","glossary":[{"word":"一程","meaning":"一段路"},{"word":"身向","meaning":"人正朝着"},{"word":"榆关","meaning":"山海关"},{"word":"那畔","meaning":"那边，畔读pàn"},{"word":"行","meaning":"行进"},{"word":"千帐灯","meaning":"许多营帐中的灯"},{"word":"一更","meaning":"一段夜间计时，更读gēng"},{"word":"聒","meaning":"声音嘈杂，读guō"},{"word":"碎","meaning":"搅碎、打断"},{"word":"乡心","meaning":"思乡之心"},{"word":"梦不成","meaning":"无法成眠或好梦难续"},{"word":"故园","meaning":"故乡"},{"word":"无此声","meaning":"没有眼前这样的风雪喧声"},{"word":"山","meaning":"山路、山岭"},{"word":"水","meaning":"水路、河流"},{"word":"夜深","meaning":"深夜"},{"word":"风","meaning":"夜里不断吹的风"},{"word":"雪","meaning":"夜里不断下的雪"}],"lines":[{"translations":["走过一程山路。","又渡过一程水路。","我正朝着山海关那边前进。","深夜里，许多营帐亮着灯。"],"reading":"山水反复写路途漫长，灯火虽多，却不能代替家的温暖。","clauses":["山一程，","水一程，","身向榆关那畔行，","夜深千帐灯。"]},{"translations":["风吹了一更又一更。","雪下了一更又一更。","嘈杂风雪搅动乡愁，令人难以成梦。","故乡没有这样的声音。"],"reading":"“故园无此声”带主观感受，不是气候调查；熟悉与陌生的声音形成对照。","clauses":["风一更，","雪一更，","聒碎乡心梦不成，","故园无此声。"]}]},"poem-73":{"title":"渔歌子","intro":"渔歌子是词牌；写春江渔者的生活意趣。","theme":"前面写景，后面写衣着与不愿归，色彩清新。“不须归”流露自在闲适，不是求生建议。","glossary":[{"word":"西塞山","meaning":"山名"},{"word":"前","meaning":"前面"},{"word":"白鹭","meaning":"白色水鸟"},{"word":"飞","meaning":"飞翔"},{"word":"桃花流水","meaning":"桃花盛开时上涨的春水"},{"word":"鳜鱼","meaning":"一种淡水鱼，鳜读guì"},{"word":"肥","meaning":"肥美"},{"word":"青箬笠","meaning":"青色竹叶编成的斗笠，箬读ruò"},{"word":"绿蓑衣","meaning":"绿色草叶编的雨衣"},{"word":"斜风","meaning":"斜斜吹来的微风"},{"word":"细雨","meaning":"细小的雨"},{"word":"不须归","meaning":"不必急着回去"}],"lines":[{"translations":["西塞山前，白鹭飞翔。","桃花盛开的春水里，鳜鱼正肥美。"],"reading":"鸟、水、花、鱼构成富有生机的春江环境。","clauses":["西塞山前白鹭飞，","桃花流水鳜鱼肥。"]},{"translations":["戴着青色斗笠。","披着绿色蓑衣。","微风细雨中，渔者不急着回去。"],"reading":"由外景写到人物装束，最后点出他对江上生活的喜爱。","clauses":["青箬笠，","绿蓑衣，","斜风细雨不须归。"]}]},"poem-74":{"title":"观书有感·其一","intro":"观书就是读书；借清澈池塘比喻读书带来的心智更新。","theme":"池塘因活水不断流入而清澈，人的认识也需要不断学习。要先懂景物本义，再体会比喻。","glossary":[{"word":"半亩","meaning":"面积不大的"},{"word":"方塘","meaning":"方形池塘"},{"word":"一鉴开","meaning":"像一面展开的镜子，鉴指镜"},{"word":"天光","meaning":"天空的光"},{"word":"云影","meaning":"云的倒影"},{"word":"共徘徊","meaning":"一起移动、荡漾"},{"word":"问渠","meaning":"问它，渠指池塘，不是水渠"},{"word":"那得","meaning":"怎么能，那同哪"},{"word":"清如许","meaning":"这样清澈，如许是这样"},{"word":"为","meaning":"因为"},{"word":"源头","meaning":"水流起点"},{"word":"活水","meaning":"不断流动更新的水"},{"word":"有","meaning":"具有、存在"},{"word":"来","meaning":"流过来"}],"lines":[{"translations":["不大的方形池塘，像一面打开的镜子。","天光云影一起在水中荡漾。"],"reading":"清澈所以能映物，用镜子比池塘，先让读者看到“清”的效果。","clauses":["半亩方塘一鉴开，","天光云影共徘徊。"]},{"translations":["问它为什么能这样清澈。","原来有源头的活水不断流进来。"],"reading":"设问之后点明原因；联系题目，可体会持续读书思考的作用。","clauses":["问渠那得清如许？","为有源头活水来。"]}]},"poem-75":{"title":"观书有感·其二","intro":"同样借具体景象写读书体会，这次选的是水涨船行。","theme":"水浅时费力，水足时顺畅，说明积累与条件成熟的重要，不是主张完全不努力。","glossary":[{"word":"昨夜","meaning":"昨天夜里"},{"word":"江边","meaning":"江中、江面"},{"word":"春水生","meaning":"春水上涨"},{"word":"蒙冲","meaning":"古代战船，这里指大船，读méng chōng"},{"word":"巨舰","meaning":"很大的船"},{"word":"一毛轻","meaning":"像一片羽毛那样轻"},{"word":"向来","meaning":"先前、从前"},{"word":"枉费","meaning":"白白花费"},{"word":"推移力","meaning":"推拉挪动船只的力气"},{"word":"此日","meaning":"今天"},{"word":"中流","meaning":"水流中央"},{"word":"自在行","meaning":"自由顺畅地行驶"}],"lines":[{"translations":["昨夜江里的春水上涨。","庞大的船只浮起来，仿佛羽毛一样轻。"],"reading":"船本身没有变轻，是水足后更容易浮行；比喻生动，不是物理重量改变。","clauses":["昨夜江边春水生，","蒙冲巨舰一毛轻。"]},{"translations":["先前白费许多推拉的力气。","今天却能在江流中自在行驶。"],"reading":"前后对照突出条件改变，联系读书可理解为积累后融会贯通。","clauses":["向来枉费推移力，","此日中流自在行。"]}]},"poem-76":{"title":"四时田园杂兴·其三十一","intro":"写夏日农村男女忙碌劳作，以及孩子模仿劳动的情景。","theme":"成人勤劳、儿童学种瓜，表现农家生活的繁忙和亲切；孩子不懂全部劳动，却有参与愿望。","glossary":[{"word":"昼","meaning":"白天"},{"word":"耘田","meaning":"在田里除草，耘读yún"},{"word":"夜","meaning":"夜晚"},{"word":"绩麻","meaning":"把麻搓接成线，绩读jì"},{"word":"村庄儿女","meaning":"村里的成年男女"},{"word":"各当家","meaning":"各自承担家务农事"},{"word":"童孙","meaning":"年幼的孩子"},{"word":"未解","meaning":"还不懂"},{"word":"供耕织","meaning":"从事耕田织布，供读gòng"},{"word":"也傍","meaning":"也靠近"},{"word":"桑阴","meaning":"桑树荫下"},{"word":"学","meaning":"模仿、学习"},{"word":"种瓜","meaning":"播种瓜类"},{"word":"出","meaning":"出门到田里劳动"}],"lines":[{"translations":["白天到田间锄草，夜里还要搓麻线。","村里的男女都各自担当着农事家务。"],"reading":"“昼”“夜”连接，写出劳动接续不断。","clauses":["昼出耘田夜绩麻，","村庄儿女各当家。"]},{"translations":["孩子还不懂怎样耕田织布。","也在桑树荫下，学着大人种瓜。"],"reading":"“也”使孩子加入劳动图景，天真模仿中含着生长与传承。","clauses":["童孙未解供耕织，","也傍桑阴学种瓜。"]}]},"poem-77":{"title":"稚子弄冰","intro":"稚子是小孩子；弄冰是把冰当玩具玩。","theme":"脱、穿、敲、碎构成小情节，声音由悦耳到破碎，既写童趣，也留下意外的转折。","glossary":[{"word":"稚子","meaning":"幼小孩子，稚读zhì"},{"word":"金盆","meaning":"金属盆，通常指铜盆，不是金子做的盆"},{"word":"脱晓冰","meaning":"取出清晨盆中的冰"},{"word":"彩丝","meaning":"彩色丝线"},{"word":"穿取","meaning":"穿过去并提起来"},{"word":"当","meaning":"当作"},{"word":"银钲","meaning":"一种金属打击乐器，钲读zhēng"},{"word":"敲成","meaning":"敲出像……的声音"},{"word":"玉磬","meaning":"玉或石制的打击乐器，磬读qìng"},{"word":"穿林响","meaning":"声音穿过树林"},{"word":"忽作","meaning":"忽然发出"},{"word":"玻璃","meaning":"古时可指天然水晶一类透明物，不宜等同现代窗玻璃"},{"word":"碎地声","meaning":"坠地碎裂的声响"}],"lines":[{"translations":["小孩子从金属盆里取出清晨结好的冰。","穿上彩色丝线，把它当成银钲来敲。"],"reading":"孩子把日常冰块想象成乐器，显示玩耍中的创造力。","clauses":["稚子金盆脱晓冰，","彩丝穿取当银钲。"]},{"translations":["敲出的声音像玉磬一样清亮，传过树林。","忽然冰落到地上，发出水晶破裂般的声音。"],"reading":"“忽”使情节突转；诗没有写孩子哭笑，留给读者想象。","clauses":["敲成玉磬穿林响，","忽作玻璃碎地声。"]}]},"poem-78":{"title":"村晚","intro":"写乡村傍晚池塘、落日与归牧儿童。","theme":"景物温润宁静，牧童横坐牛背、随口吹笛，表现自在无拘的乡村生活。","glossary":[{"word":"草满池塘","meaning":"池塘周围草茂盛"},{"word":"水满陂","meaning":"池塘水很满，陂读bēi"},{"word":"山衔落日","meaning":"落日将沉，像被山含在口中"},{"word":"浸","meaning":"映入、倒映"},{"word":"寒漪","meaning":"带凉意的水波，漪读yī"},{"word":"牧童","meaning":"放牧孩子"},{"word":"归去","meaning":"回家"},{"word":"横牛背","meaning":"横坐在牛背上"},{"word":"短笛","meaning":"短小笛子"},{"word":"无腔","meaning":"不按固定曲调"},{"word":"信口吹","meaning":"随口吹奏"}],"lines":[{"translations":["池塘边长满了草，塘水也很满。","落日像被山含住，倒映在清凉的水波里。"],"reading":"“衔”把山写活，“浸”把山日与水连在一起。","clauses":["草满池塘水满陂，","山衔落日浸寒漪。"]},{"translations":["牧童回家，横坐在牛背上。","拿着短笛，不照曲调，随口吹着。"],"reading":"“横”“信口”写姿态和声音的自在，不是评价乐曲水平。","clauses":["牧童归去横牛背，","短笛无腔信口吹。"]}]},"poem-79":{"title":"游子吟","intro":"游子是远离家乡的人；吟是吟咏；写母亲缝衣与儿子感恩。","theme":"前半用密密缝衣表现牵挂，结尾以小草与春日阳光比喻子女心意与母爱，抒发难以报答的感受。","glossary":[{"word":"慈母","meaning":"慈爱的母亲"},{"word":"手中线","meaning":"手里缝衣的针线"},{"word":"游子","meaning":"远行在外的人"},{"word":"身上衣","meaning":"身上穿的衣服"},{"word":"临行","meaning":"将要出门"},{"word":"密密缝","meaning":"一针一针缝得细密"},{"word":"意恐","meaning":"心里担心"},{"word":"迟迟归","meaning":"很久不能回来"},{"word":"谁言","meaning":"谁说，反问"},{"word":"寸草心","meaning":"小草微小的心意，比喻子女的感恩"},{"word":"报得","meaning":"能够报答"},{"word":"三春晖","meaning":"春天的阳光，比喻母爱"},{"word":"三春","meaning":"春季的三个月"},{"word":"晖","meaning":"阳光"}],"lines":[{"translations":["慈母手中拿着针线。","为将远行的儿子缝制衣裳。"],"reading":"两句把线与衣、母与子连在一起，感情藏在劳动中。","clauses":["慈母手中线，","游子身上衣。"]},{"translations":["临出门时，她把针脚缝得细而密。","心里担心儿子很晚才能回来。"],"reading":"缝得牢，是担心衣服穿久了破；动作具体表现牵挂。","clauses":["临行密密缝，","意恐迟迟归。"]},{"translations":["谁能说，像小草一样微小的孝心。","就能报答春日阳光般深厚的母爱呢？"],"reading":"不是说不必报答，而是感叹养育之恩深厚，激发珍惜与感恩。","clauses":["谁言寸草心，","报得三春晖。"]}]},"poem-80":{"title":"鸟鸣涧","intro":"涧是山间溪流；写春夜山中花落、月出、鸟鸣的细微变化。","theme":"“闲”是感受环境的条件。声音与动作都很轻，反衬夜晚幽静，不是写喧闹山林。","glossary":[{"word":"人闲","meaning":"人心安闲"},{"word":"桂花落","meaning":"桂花飘落，桂的品种与花期可有讨论，不必强定秋桂"},{"word":"夜静","meaning":"夜里安静"},{"word":"春山空","meaning":"春夜山林空寂"},{"word":"月出","meaning":"月亮升起"},{"word":"惊","meaning":"惊动"},{"word":"山鸟","meaning":"山里的鸟"},{"word":"时鸣","meaning":"不时鸣叫"},{"word":"春涧中","meaning":"春天的山涧之中"}],"lines":[{"translations":["人心安闲，能感到桂花轻轻飘落。","夜晚静悄悄，春山显得空寂。"],"reading":"细小花落之所以可感，正因为人闲、夜静。","clauses":["人闲桂花落，","夜静春山空。"]},{"translations":["月亮升起，惊动了山鸟。","它们不时在春夜的山涧中叫几声。"],"reading":"鸟鸣是间歇的，短暂声音让整体宁静更明显。","clauses":["月出惊山鸟，","时鸣春涧中。"]}]},"poem-81":{"title":"从军行","intro":"从军是参军；这是边塞题材的乐府诗。","theme":"苍茫景色交代艰苦环境，百战磨甲显示长期征战，末句表达将士坚定的守边意志。","glossary":[{"word":"青海","meaning":"青海湖一带"},{"word":"长云","meaning":"绵延的云层"},{"word":"暗","meaning":"使昏暗"},{"word":"雪山","meaning":"积雪山脉"},{"word":"孤城","meaning":"孤立的边城"},{"word":"遥望","meaning":"远远望去"},{"word":"玉门关","meaning":"古代边关"},{"word":"黄沙","meaning":"沙漠、风沙"},{"word":"百战","meaning":"经历多次战斗"},{"word":"穿","meaning":"磨破"},{"word":"金甲","meaning":"金属铠甲"},{"word":"不破","meaning":"不打败"},{"word":"楼兰","meaning":"古代西域地名，此处借指敌方"},{"word":"终不还","meaning":"始终不返回"}],"lines":[{"translations":["青海一带云层绵延，遮暗了雪山。","孤立的边城，遥对着远方玉门关。"],"reading":"地名共同构成辽阔边地画卷，不必当成一张单点实景地图。","clauses":["青海长云暗雪山，","孤城遥望玉门关。"]},{"translations":["在黄沙中经历多次战斗，铠甲都磨破了。","若不打败来犯之敌，就决不回还。"],"reading":"“穿”写艰苦，“终不还”写决心，形成由景到志的推进。","clauses":["黄沙百战穿金甲，","不破楼兰终不还。"]}]},"poem-82":{"title":"秋夜将晓出篱门迎凉有感","intro":"将晓是天快亮；迎凉是出门感受凉意；诗人想到北方失地与百姓。","theme":"黄河华山写山河壮阔，遗民流泪写苦难，最后的“又一年”写等待一次次落空。","glossary":[{"word":"三万里河","meaning":"绵长黄河，三万里为夸张"},{"word":"东入海","meaning":"向东流入海洋"},{"word":"五千仞岳","meaning":"高耸的西岳华山，仞是古长度单位，数字为夸张"},{"word":"上摩天","meaning":"高接天空，摩是接触"},{"word":"遗民","meaning":"沦陷区仍盼故国的百姓"},{"word":"泪尽","meaning":"眼泪仿佛流尽"},{"word":"胡尘","meaning":"古诗中对入侵战乱及其统治的说法"},{"word":"南望","meaning":"向南眺望"},{"word":"王师","meaning":"宋朝军队"},{"word":"又一年","meaning":"又过去了一年"},{"word":"里","meaning":"之中，表示所处环境"}],"lines":[{"translations":["绵长的黄河向东流入大海。","高高的华山直插云天。"],"reading":"先写壮丽国土，为失地与百姓的悲苦增添分量。","clauses":["三万里河东入海，","五千仞岳上摩天。"]},{"translations":["沦陷地区的百姓在战乱统治下仿佛流尽了眼泪。","他们望着南方，盼朝廷军队，又等过了一年。"],"reading":"“尽”写痛苦，“又”写失望积累，也包含对朝廷迟迟不行动的忧愤。","clauses":["遗民泪尽胡尘里，","南望王师又一年。"]}]},"poem-83":{"title":"闻官军收河南河北","intro":"闻是听说；河南河北在这里主要指黄河以南以北的地区，不能直接等同今天两省。","theme":"突闻收复消息，泪、笑、歌、酒、归程接连涌出，把喜极的心理写得迅疾有力。","glossary":[{"word":"剑外","meaning":"剑门关以南的蜀地"},{"word":"忽传","meaning":"忽然传来消息"},{"word":"收蓟北","meaning":"收复蓟北地区，蓟读jì"},{"word":"初闻","meaning":"刚刚听说"},{"word":"涕泪","meaning":"眼泪"},{"word":"衣裳","meaning":"衣服"},{"word":"却看","meaning":"回头看"},{"word":"妻子","meaning":"妻子与孩子，古今义不同"},{"word":"愁何在","meaning":"愁已消失"},{"word":"漫卷","meaning":"随意卷起"},{"word":"喜欲狂","meaning":"高兴得几乎发狂"},{"word":"放歌","meaning":"放声歌唱"},{"word":"须","meaning":"应该、尽可"},{"word":"纵酒","meaning":"尽情饮酒的诗中表达"},{"word":"青春","meaning":"春天的景色，不是青年时期"},{"word":"作伴","meaning":"陪伴"},{"word":"还乡","meaning":"回故乡"},{"word":"即从","meaning":"立即就从"},{"word":"巴峡","meaning":"川东一带峡谷"},{"word":"穿","meaning":"经过"},{"word":"巫峡","meaning":"长江三峡之一"},{"word":"便下","meaning":"便顺流而下"},{"word":"襄阳","meaning":"地名"},{"word":"向洛阳","meaning":"往洛阳去"},{"word":"满","meaning":"沾满、布满"},{"word":"诗书","meaning":"诗集与书籍"},{"word":"白日","meaning":"白天"},{"word":"好","meaning":"适宜、正好"}],"lines":[{"translations":["蜀地忽然传来收复蓟北的消息。","刚听见，我的眼泪就打湿衣服。"],"reading":"开篇“忽”“初”接连写突然，泪是长期压抑后喜极而泣。","clauses":["剑外忽传收蓟北，","初闻涕泪满衣裳。"]},{"translations":["回头看妻子孩子，愁云早已消散。","随手卷起诗书，欢喜得几乎发狂。"],"reading":"“妻子”包括孩子；情绪从个人扩展到全家。","clauses":["却看妻子愁何在，","漫卷诗书喜欲狂。"]},{"translations":["白日里尽可放声唱歌，表达畅快。","春光陪伴着，正好启程回乡。"],"reading":"“青春”在这里是明媚的春景，不是年轻的年岁；春光陪伴归途，显出希望。","clauses":["白日放歌须纵酒，","青春作伴好还乡。"]},{"translations":["立刻从巴峡经过巫峡。","再顺路经过襄阳，奔向洛阳。"],"reading":"这是想象的归途，不是诗人已经走完；“即”“穿”“便”“向”显出急切。","clauses":["即从巴峡穿巫峡，","便下襄阳向洛阳。"]}]},"poem-84":{"title":"凉州词（黄河远上白云间）","intro":"以边城、羌笛写戍边环境与乡情。","theme":"壮阔黄河与孤城相对，后半借笛曲与春风写关外荒寒。“杨柳”既关曲名，也引离别联想。","glossary":[{"word":"黄河远上","meaning":"远望黄河，好像上接天际"},{"word":"白云间","meaning":"白云缭绕之处"},{"word":"一片孤城","meaning":"一座孤零零的边城"},{"word":"万仞山","meaning":"极高的山，仞是古长度单位"},{"word":"羌笛","meaning":"古代羌族的一种笛"},{"word":"何须","meaning":"何必"},{"word":"怨杨柳","meaning":"因吹奏《折杨柳》而含怨，杨柳指曲名并关联离别"},{"word":"春风","meaning":"春天的风，也可寄托温暖关怀"},{"word":"不度","meaning":"吹不过、不到"},{"word":"玉门关","meaning":"古代边关"}],"lines":[{"translations":["远望黄河，仿佛上接白云。","极高的群山间，孤零零地立着一座边城。"],"reading":"大河高山写壮阔，“一片孤城”把人的孤寂放入广阔背景。","clauses":["黄河远上白云间，","一片孤城万仞山。"]},{"translations":["羌笛何必吹起哀怨的《折杨柳》呢？","这里本就是春风难到的玉门关外。"],"reading":"以劝慰语写难解乡愁；“不度”是边地荒寒的诗意表达，非绝对气象事实。","clauses":["羌笛何须怨杨柳，","春风不度玉门关。"]}]},"poem-85":{"title":"黄鹤楼送孟浩然之广陵","intro":"广陵是今扬州；送别友人孟浩然东去。","theme":"先写明媚春日与行程，后写一直目送到帆影消失。没有直说难舍，却处处是深情。","glossary":[{"word":"故人","meaning":"老朋友"},{"word":"西辞","meaning":"从西边辞别，黄鹤楼在扬州西面"},{"word":"黄鹤楼","meaning":"名楼，在今武汉"},{"word":"烟花","meaning":"烟雾迷蒙、繁花盛放的春景，不是烟火"},{"word":"三月","meaning":"农历三月"},{"word":"下扬州","meaning":"顺江到扬州去"},{"word":"孤帆","meaning":"一只船的帆，代友人的船"},{"word":"远影","meaning":"远去的影子"},{"word":"碧空尽","meaning":"消失在碧蓝天际"},{"word":"唯见","meaning":"只看见"},{"word":"长江","meaning":"江名"},{"word":"天际流","meaning":"流向天边"}],"lines":[{"translations":["老朋友辞别西边的黄鹤楼。","在繁花如烟的三月，顺江前往扬州。"],"reading":"“烟花”点出盛春时节，使离别景色明丽而非阴沉。","clauses":["故人西辞黄鹤楼，","烟花三月下扬州。"]},{"translations":["孤帆的影子远去，最后消失在蓝天尽头。","只见长江仍向天边流去。"],"reading":"“唯见”暗示人还站着目送，以持续注视表达眷恋。","clauses":["孤帆远影碧空尽，","唯见长江天际流。"]}]},"poem-86":{"title":"乡村四月","intro":"写农历四月江南农村的景色与忙碌农事。","theme":"山绿水白、鸟声烟雨先写环境；养蚕插秧再写劳动，景美而人勤。","glossary":[{"word":"绿遍","meaning":"到处碧绿"},{"word":"山原","meaning":"山坡原野"},{"word":"白满川","meaning":"水田水光遍地，川指平地"},{"word":"子规","meaning":"杜鹃鸟"},{"word":"声里","meaning":"鸣叫声中"},{"word":"雨如烟","meaning":"细雨像烟雾"},{"word":"闲人少","meaning":"空闲的人少"},{"word":"才了","meaning":"刚刚做完，了读liǎo"},{"word":"蚕桑","meaning":"养蚕采桑等事务"},{"word":"又","meaning":"紧接着"},{"word":"插田","meaning":"插秧"},{"word":"乡村四月","meaning":"农历四月的乡村，农事繁忙的时节"}],"lines":[{"translations":["山坡原野一片碧绿，水田映出白亮水光。","杜鹃鸣叫声中，细雨像轻烟一样飘着。"],"reading":"颜色、声音、雨雾相结合，组成湿润的江南初夏景。","clauses":["绿遍山原白满川，","子规声里雨如烟。"]},{"translations":["四月的乡村很少有人闲着。","才做完蚕桑的活，又忙着下田插秧。"],"reading":"“才”“又”紧接，写出农时不等人的繁忙。","clauses":["乡村四月闲人少，","才了蚕桑又插田。"]}]},"poem-87":{"title":"宿建德江","intro":"宿是住宿、夜泊；建德江在今浙江建德一带。","theme":"日暮引发旅愁，旷野、低天、近月形成独特夜景。月既衬孤独，也仿佛陪伴着旅人。","glossary":[{"word":"移舟","meaning":"移动小船"},{"word":"泊","meaning":"停船，读bó"},{"word":"烟渚","meaning":"烟雾笼罩的水中小洲，渚读zhǔ"},{"word":"日暮","meaning":"太阳将落、黄昏"},{"word":"客愁","meaning":"旅人的愁绪"},{"word":"新","meaning":"新生、又生"},{"word":"野旷","meaning":"原野开阔"},{"word":"天低树","meaning":"远处天幕仿佛低于近处树梢"},{"word":"江清","meaning":"江水清澈"},{"word":"月近人","meaning":"水中月影仿佛靠近船中的人"}],"lines":[{"translations":["把船停靠在烟雾笼罩的小洲旁。","黄昏来临，旅人的愁绪又涌上心头。"],"reading":"“新”不是从未有过愁，而是眼前日暮又触发了一层愁。","clauses":["移舟泊烟渚，","日暮客愁新。"]},{"translations":["原野辽阔，远天仿佛低在树梢下。","江水清澈，月影仿佛贴近船里的人。"],"reading":"“低”“近”写观察感受，不是天空高度或月地距离真的改变。","clauses":["野旷天低树，","江清月近人。"]}]},"poem-88":{"title":"六月二十七日望湖楼醉书","intro":"题目记写作时日和地点；望湖楼在杭州西湖边。","theme":"黑云、白雨、急风、开晴依次变化，速度快、色彩强，像记录一场骤雨的镜头。","glossary":[{"word":"黑云","meaning":"乌黑的云"},{"word":"翻墨","meaning":"像翻倒的墨汁，写云黑且翻动"},{"word":"未遮山","meaning":"还没完全遮住山"},{"word":"白雨","meaning":"白亮急密的雨"},{"word":"跳珠","meaning":"像跳动的珍珠"},{"word":"乱入船","meaning":"纷乱地打进船里"},{"word":"卷地风","meaning":"贴地卷来的风"},{"word":"忽","meaning":"忽然"},{"word":"吹散","meaning":"把云雨吹开"},{"word":"望湖楼","meaning":"楼名"},{"word":"水如天","meaning":"湖水开阔明净，像天空一样"},{"word":"来","meaning":"到来、吹来"},{"word":"下","meaning":"楼的下面"}],"lines":[{"translations":["黑云像打翻的浓墨，还未来得及遮住山。","白亮雨点像跳动珍珠，纷纷打进船里。"],"reading":"黑白对照，“翻”“跳”“乱”都写骤雨的急动。","clauses":["黑云翻墨未遮山，","白雨跳珠乱入船。"]},{"translations":["一阵卷地的大风忽然吹来，把云雨吹散。","望湖楼下，湖水又明净得像天空。"],"reading":"从急雨到开晴只在转瞬，末句用开阔平静收束。","clauses":["卷地风来忽吹散，","望湖楼下水如天。"]}]},"poem-89":{"title":"西江月·夜行黄沙道中","intro":"西江月是词牌；黄沙是地名，写夏夜行路所闻所见。","theme":"鸟蝉蛙声、稻花香与稀星小雨组成乡村夏夜。结尾转路见旧店，带有意外找到歇脚处的欣喜。","glossary":[{"word":"明月","meaning":"明亮月光"},{"word":"别枝惊鹊","meaning":"月光惊动枝上的喜鹊，别枝有不同解释，常理解为旁枝"},{"word":"清风","meaning":"清凉的风"},{"word":"半夜","meaning":"深夜"},{"word":"鸣蝉","meaning":"蝉在鸣叫"},{"word":"稻花香","meaning":"水稻开花的香气"},{"word":"说丰年","meaning":"仿佛谈论丰收，也可理解为人在谈论"},{"word":"听取","meaning":"听着"},{"word":"一片","meaning":"连成一片"},{"word":"七八个星","meaning":"稀疏的几颗星"},{"word":"天外","meaning":"远天"},{"word":"两三点雨","meaning":"零星雨滴"},{"word":"山前","meaning":"山的前面"},{"word":"旧时","meaning":"往日熟悉的"},{"word":"茅店","meaning":"茅草盖的乡村小店"},{"word":"社林","meaning":"土地庙附近的树林"},{"word":"路转","meaning":"山路拐弯"},{"word":"溪桥","meaning":"溪上的桥"},{"word":"忽见","meaning":"忽然出现，见常按xiàn理解，依课本读音"},{"word":"里","meaning":"之中"},{"word":"蛙声","meaning":"青蛙的叫声"},{"word":"边","meaning":"旁边"}],"lines":[{"translations":["明亮月光惊动了树枝上的喜鹊。","清凉夜风中，传来蝉鸣。"],"reading":"月光与风是背景，鸟鸣蝉声使夜行场景有声有色。","clauses":["明月别枝惊鹊，","清风半夜鸣蝉。"]},{"translations":["稻花香里，仿佛在谈论丰收年景。","听，那蛙声连成一片。"],"reading":"把蛙鸣和丰收联想相连，寄托对庄稼好收成的欣喜。","clauses":["稻花香里说丰年，","听取蛙声一片。"]},{"translations":["远天闪着几颗稀星。","山前落下了两三点雨。"],"reading":"星疏雨稀，天气正在变化，也引出寻找小店的需要。","clauses":["七八个星天外，","两三点雨山前。"]},{"translations":["往日熟悉的茅草小店，本在社林旁边。","道路转过溪桥，它忽然出现在眼前。"],"reading":"“忽见”把先前的遮挡与此刻的发现写出来，收尾亲切明快。","clauses":["旧时茅店社林边，","路转溪桥忽见。"]}]},"poem-90":{"title":"过故人庄","intro":"过是拜访；故人是老朋友；庄是农庄。","theme":"备饭、邀客、看景、聊天、再约重来，层层写朋友交往的朴素真诚。","glossary":[{"word":"故人","meaning":"老朋友"},{"word":"具","meaning":"准备"},{"word":"鸡黍","meaning":"鸡肉与黍米饭，黍读shǔ"},{"word":"邀","meaning":"邀请"},{"word":"至","meaning":"到"},{"word":"田家","meaning":"农家"},{"word":"绿树","meaning":"绿色树木"},{"word":"合","meaning":"环绕"},{"word":"青山","meaning":"青色山峦"},{"word":"郭外","meaning":"村郭外面"},{"word":"斜","meaning":"斜斜伸展"},{"word":"开轩","meaning":"打开窗户"},{"word":"面","meaning":"面对"},{"word":"场圃","meaning":"打谷场与菜园"},{"word":"把酒","meaning":"端着酒杯"},{"word":"话桑麻","meaning":"谈论农事"},{"word":"待到","meaning":"等到"},{"word":"重阳日","meaning":"农历九月初九"},{"word":"还来","meaning":"再来"},{"word":"就菊花","meaning":"来赏菊、亲近菊花"},{"word":"我","meaning":"来访做客的诗人"},{"word":"村边","meaning":"村庄周边"}],"lines":[{"translations":["老朋友准备了鸡肉和米饭。","邀请我到他的农家做客。"],"reading":"饭食普通，款待真诚，诗的亲切感从开头就建立起来。","clauses":["故人具鸡黍，","邀我至田家。"]},{"translations":["绿树环绕着村庄。","青山在村外斜斜伸向远方。"],"reading":"近树远山，构成自然开阔的乡村环境。","clauses":["绿树村边合，","青山郭外斜。"]},{"translations":["打开窗户，面对打谷场与菜园。","举杯交谈，说的都是桑麻农事。"],"reading":"“桑麻”代农事，谈话平常，正显出朋友之间无需客套。","clauses":["开轩面场圃，","把酒话桑麻。"]},{"translations":["等到重阳节那一天。","我还要再来这里赏菊。"],"reading":"客未走便约重来，不直说难舍，却充分流露留恋。","clauses":["待到重阳日，","还来就菊花。"]}]},"poem-91":{"title":"春日","intro":"表面写春日寻芳，也常被理解为借春景表达学习求道的感受。","theme":"先写整体一新，再写万紫千红。自然之春与思想活力的联想可以并存，不必把实景考证得过死。","glossary":[{"word":"胜日","meaning":"天气晴好的日子"},{"word":"寻芳","meaning":"寻找、欣赏春景"},{"word":"泗水滨","meaning":"泗水岸边，泗读sì，滨是水边"},{"word":"无边","meaning":"无边无际"},{"word":"光景","meaning":"风光景物"},{"word":"一时新","meaning":"一下呈现新面貌"},{"word":"等闲","meaning":"轻易、平常地"},{"word":"识得","meaning":"认出"},{"word":"东风面","meaning":"春风的面貌，以东风指春天"},{"word":"万紫千红","meaning":"各色花卉争艳"},{"word":"总是春","meaning":"处处都是春意"}],"lines":[{"translations":["晴好的日子里，到泗水岸边寻找春景。","无边风光，一下都显出新的面貌。"],"reading":"“新”是总感受，后面用具体花色解释这种新。","clauses":["胜日寻芳泗水滨，","无边光景一时新。"]},{"translations":["很容易就能认出春风的面容。","那万紫千红的景色，处处都是春天。"],"reading":"春风无形，却能由百花看见它的作用，这是由结果认识力量。","clauses":["等闲识得东风面，","万紫千红总是春。"]}]},"poem-92":{"title":"回乡偶书","intro":"偶书是偶然有感而写；写离乡多年后回到家乡的感受。","theme":"乡音未改，容颜已老；自己是归人，孩子却认作客人。笑问之中含着时光流逝的复杂心情。","glossary":[{"word":"少小","meaning":"年少时"},{"word":"离家","meaning":"离开家乡"},{"word":"老大","meaning":"年老时，不是排行最大"},{"word":"回","meaning":"回来"},{"word":"乡音","meaning":"家乡口音"},{"word":"无改","meaning":"没有改变"},{"word":"鬓毛衰","meaning":"鬓边毛发稀疏或变白，鬓读bìn，衰的读音依课本"},{"word":"儿童","meaning":"当地孩子"},{"word":"相见","meaning":"见到我"},{"word":"不相识","meaning":"不认识我"},{"word":"笑问","meaning":"笑着问"},{"word":"客","meaning":"外来的客人"},{"word":"何处来","meaning":"从哪里来"},{"word":"从","meaning":"自、由"}],"lines":[{"translations":["年少时离开家乡，年老才回来。","乡音没有变，鬓发却已经衰白。"],"reading":"少与老、未改与已衰相对，几十年的变化浓缩在两句中。","clauses":["少小离家老大回，","乡音无改鬓毛衰。"]},{"translations":["孩子们见了我，却并不认识。","笑着问：这位客人，你是从哪里来的？"],"reading":"孩子的天真问话并无恶意，却让归乡人感到自己离开太久。","clauses":["儿童相见不相识，","笑问客从何处来。"]}]},"poem-93":{"title":"浪淘沙·其一","intro":"浪淘沙原为曲调名；诗以黄河为起点，展开浪漫想象。","theme":"先写万里黄沙、风浪颠簸，再想象直上银河访牛郎织女，表现雄奇开阔的气概。","glossary":[{"word":"九曲","meaning":"弯弯曲曲，不一定恰九个弯"},{"word":"黄河","meaning":"河名"},{"word":"万里沙","meaning":"长河挟带很多泥沙"},{"word":"浪淘","meaning":"波浪淘洗"},{"word":"风簸","meaning":"风使波浪颠簸，簸读bǒ"},{"word":"自天涯","meaning":"从极远处来"},{"word":"如今","meaning":"现在"},{"word":"直上","meaning":"一直向上"},{"word":"银河","meaning":"天上星河"},{"word":"同到","meaning":"一同到达"},{"word":"牵牛织女家","meaning":"神话中牛郎织女居处"},{"word":"去","meaning":"前往"}],"lines":[{"translations":["弯弯曲曲的黄河，挟着万里泥沙。","波浪淘洗、狂风颠簸，从遥远天边奔来。"],"reading":"动词连续，写黄河水势的雄壮，不是平静的风景照。","clauses":["九曲黄河万里沙，","浪淘风簸自天涯。"]},{"translations":["现在就沿着它直上银河。","一同到牛郎织女的家中去。"],"reading":"后两句由实景转入想象，黄河与银河在诗意中相通。","clauses":["如今直上银河去，","同到牵牛织女家。"]}]},"poem-94":{"title":"江南春","intro":"概写江南春景，并把眼前烟雨与南朝寺院联系。","theme":"声色明丽的水村山郭，与烟雨中朦胧楼台形成层次；“千里”“四百八十”都不宜机械计数。","glossary":[{"word":"千里","meaning":"广阔的江南大地"},{"word":"莺啼","meaning":"黄莺鸣叫"},{"word":"绿映红","meaning":"绿树映衬红花"},{"word":"水村","meaning":"临水村庄"},{"word":"山郭","meaning":"靠山的城镇"},{"word":"酒旗风","meaning":"酒家旗帜迎风飘动"},{"word":"南朝","meaning":"东晋后南方几个朝代的总称"},{"word":"四百八十寺","meaning":"寺院很多，非要求准确计数"},{"word":"多少楼台","meaning":"许多寺庙楼阁"},{"word":"烟雨中","meaning":"朦胧细雨之中"}],"lines":[{"translations":["广阔江南，黄莺啼唱，绿树红花相映。","水边村落、山旁城镇，酒旗迎风飘扬。"],"reading":"视觉、听觉与风中动态合写，春景富有生活气息。","clauses":["千里莺啼绿映红，","水村山郭酒旗风。"]},{"translations":["南朝留下的众多寺院。","多少楼台，如今掩映在迷蒙烟雨中。"],"reading":"景物带出历史层次，语气有追怀意味，具体讽喻解读可有不同。","clauses":["南朝四百八十寺，","多少楼台烟雨中。"]}]},"poem-95":{"title":"书湖阴先生壁","intro":"书是题写；湖阴先生是诗人的友人杨德逢；壁是墙。","theme":"庭院整洁、花木自栽写主人品性，山水仿佛主动来亲近，展现人与自然的亲密关系。","glossary":[{"word":"茅檐","meaning":"茅屋檐下，也指庭院"},{"word":"长扫","meaning":"经常打扫，长同常"},{"word":"净无苔","meaning":"干净得没有青苔"},{"word":"成畦","meaning":"分成整齐的畦，畦读qí"},{"word":"手自栽","meaning":"亲手种植"},{"word":"一水","meaning":"一条溪水"},{"word":"护田","meaning":"像守护田地"},{"word":"将绿绕","meaning":"把绿色田地环绕起来，将是把"},{"word":"两山","meaning":"两座山"},{"word":"排闼","meaning":"推开门，闼读tà"},{"word":"送青来","meaning":"送来青翠山色"},{"word":"花木","meaning":"花草树木"}],"lines":[{"translations":["茅屋庭院常常打扫，干净得没有青苔。","花木排列整齐，都是主人亲手栽种。"],"reading":"不直接夸人，而由环境整洁与亲手劳动表现主人的情趣。","clauses":["茅檐长扫净无苔，","花木成畦手自栽。"]},{"translations":["一条溪水像护着田地，把绿色环绕。","两座青山仿佛推门而入，送来青翠。"],"reading":"“护”“排闼”“送”都是拟人，山水与居者像亲切的朋友。","clauses":["一水护田将绿绕，","两山排闼送青来。"]}]},"poem-96":{"title":"七律·长征","intro":"七律是七言律诗，每句七字，共八句；长征指红军的长途战略转移。正文请结合课本阅读。","theme":"全诗以山河险阻反衬队伍的坚韧与乐观。把巨大山岭写得轻小，是表达不畏困难的精神，并不否认实际牺牲与艰辛。","glossary":[{"word":"七律","meaning":"七言律诗，通常八句"},{"word":"长征","meaning":"这里指红军长征"},{"word":"等闲","meaning":"平常、不放在心上"},{"word":"逶迤","meaning":"曲折绵延，读wēi yí"},{"word":"磅礴","meaning":"雄伟广大，读páng bó"},{"word":"云崖","meaning":"高耸入云的山崖"},{"word":"三军","meaning":"这里泛指红军队伍"},{"word":"开颜","meaning":"露出笑容"}],"lines":[{"translations":["开篇说明，队伍面对漫长远征并不退缩。","绵延山川与无数艰险，被放在勇往直前的气概中来看。"],"reading":"先确立全诗精神，再展开具体山水经历，属于总起。","label":"第1层意思"},{"translations":["连绵的五岭，在坚强意志面前仿佛只是一点波动。","雄伟的乌蒙山，也被想象为轻小的土丸。"],"reading":"大小悬殊的夸张，表现精神上藐视艰险；不是山实际很小。","label":"第2层意思"},{"translations":["渡过金沙江的经历带来喜悦和振奋。","大渡河上的铁索桥又使人感到险峻紧张。"],"reading":"用温暖与寒意的感受组织不同险境，不宜只译为天气冷热。","label":"第3层意思"},{"translations":["越过终年积雪的岷山，更令人欣喜。","回望艰苦历程，队伍迎来共同的欢笑。"],"reading":"结尾由险阻转向胜利信心，承接开头的乐观精神。","label":"第4层意思"}]},"poem-97":{"title":"菩萨蛮·大柏地","intro":"菩萨蛮是词牌，大柏地是地名。正文请结合课本阅读；以下依上、下片的顺序解释。","theme":"雨后彩虹与旧日战场交叠，把历史记忆融入今日景色。墙上弹痕本是战争痕迹，在回望中又承载奋斗记忆。","glossary":[{"word":"菩萨蛮","meaning":"词牌名"},{"word":"大柏地","meaning":"江西瑞金附近地名"},{"word":"关山","meaning":"山岭"},{"word":"残阳","meaning":"将落的太阳"},{"word":"鏖战","meaning":"激烈战斗，鏖读áo"},{"word":"弹洞","meaning":"子弹留下的洞痕"},{"word":"装点","meaning":"点缀"},{"word":"今朝","meaning":"今天、如今，朝读zhāo"}],"lines":[{"translations":["天空出现红橙黄绿等颜色组成的彩虹。","仿佛有人在高空挥舞彩色长带，词人不禁发出惊奇的询问。"],"reading":"彩虹被比作舞动的长带，想象中的持带者使天空有了动态；并非实写虹下人群。","label":"第1层意思"},{"translations":["雨后的夕阳再次照亮山岭。","层层山色在斜照中显得青翠。"],"reading":"天气由雨到晴，颜色与光线推动画面变化。","label":"第2层意思"},{"translations":["眼前山村曾经发生激烈战斗。","如今墙上的弹痕仍可看见。"],"reading":"由当前景色转入历史记忆，空间相同，时间不同。","label":"第3层意思"},{"translations":["这些旧日痕迹进入今天的风景。","它们因承载战斗记忆而引出新的感受。"],"reading":"结尾把伤痕与回望联系起来；这份新的感受来自对往事的回望，把自然景色与历史经历相连。","label":"第4层意思"}]},"poem-98":{"title":"寒食","intro":"寒食是传统节日，古时有禁火等习俗；诗写长安暮春与宫廷赐火。","theme":"前半春景明丽，后半视线集中到受赐之家，形成宫廷特权的意味；是否着重讽刺可有不同理解。","glossary":[{"word":"春城","meaning":"春天的京城长安"},{"word":"无处不","meaning":"到处都"},{"word":"飞花","meaning":"随风飘落的花"},{"word":"寒食","meaning":"清明前后传统节日"},{"word":"东风","meaning":"春风"},{"word":"御柳","meaning":"皇宫园中的柳树"},{"word":"斜","meaning":"斜拂"},{"word":"日暮","meaning":"傍晚"},{"word":"汉宫","meaning":"借汉代宫廷指唐宫"},{"word":"传蜡烛","meaning":"宫中传赐新火、蜡烛"},{"word":"轻烟","meaning":"细淡的烟"},{"word":"散入","meaning":"飘入"},{"word":"五侯家","meaning":"借指权贵之家"}],"lines":[{"translations":["春日长安，到处都有花瓣飞舞。","寒食时的春风，吹斜了宫苑柳条。"],"reading":"“无处不”是双重否定，意思是处处都有。","clauses":["春城无处不飞花，","寒食东风御柳斜。"]},{"translations":["傍晚，宫中传赐蜡烛。","轻烟飘入受宠权贵的家门。"],"reading":"联系寒食禁火习俗，才能理解赐火为何显得特殊。","clauses":["日暮汉宫传蜡烛，","轻烟散入五侯家。"]}]},"poem-99":{"title":"迢迢牵牛星","intro":"选自《古诗十九首》，借牛郎织女隔河相望写相思与阻隔。","theme":"叠词从距离、明亮、手形、织声到眼神，细腻地写思念。近在一水之间，却不能交谈，反差最为动人。","glossary":[{"word":"迢迢","meaning":"遥远的样子，读tiáo tiáo"},{"word":"牵牛星","meaning":"牛郎星"},{"word":"皎皎","meaning":"明亮洁白的样子，读jiǎo jiǎo"},{"word":"河汉女","meaning":"银河边的织女"},{"word":"纤纤","meaning":"细长柔美，读xiān xiān"},{"word":"擢","meaning":"伸出，读zhuó"},{"word":"素手","meaning":"白皙的手"},{"word":"札札","meaning":"织机声，读zhá zhá"},{"word":"弄","meaning":"摆弄"},{"word":"机杼","meaning":"织布机及梭子，杼读zhù"},{"word":"终日","meaning":"整天"},{"word":"不成章","meaning":"织不成布匹上的纹理，章指花纹"},{"word":"泣涕","meaning":"眼泪"},{"word":"零","meaning":"落下"},{"word":"河汉","meaning":"银河"},{"word":"清且浅","meaning":"清澈而又浅"},{"word":"相去","meaning":"相距"},{"word":"复几许","meaning":"又有多远，几许是多少"},{"word":"盈盈","meaning":"常解为水清浅的样子，也有形容人物仪态之说"},{"word":"一水间","meaning":"隔着一条水，间表示间隔"},{"word":"脉脉","meaning":"含情相视，读mò mò"},{"word":"不得语","meaning":"不能说话"},{"word":"如雨","meaning":"像雨点一样，形容眼泪很多"}],"lines":[{"translations":["遥远的是牵牛星。","明亮的是银河边的织女星。"],"reading":"先把一对星辰写成人，奠定神话与人间相思相通的情境。","clauses":["迢迢牵牛星，","皎皎河汉女。"]},{"translations":["织女伸出细长白皙的双手。","摆弄织机，发出札札的织布声。"],"reading":"手的形态与机杼声音都很具体，写她看似在劳动。","clauses":["纤纤擢素手，","札札弄机杼。"]},{"translations":["可是一整天，也织不成有纹理的布。","思念使她的眼泪像雨一样落下。"],"reading":"劳作难成的原因是心不在焉，“零”是落，不是数目零。","clauses":["终日不成章，","泣涕零如雨。"]},{"translations":["银河清澈，又显得很浅。","彼此相距，到底能有多远呢？"],"reading":"问的不是天文学距离，而是以看似接近反衬不能相会。","clauses":["河汉清且浅，","相去复几许。"]},{"translations":["只隔着一条清浅的银河。","却只能含情相望，不能交谈。"],"reading":"以“近”写“远”，身体距离不大，情感阻隔却难跨越。","clauses":["盈盈一水间，","脉脉不得语。"]}]},"poem-100":{"title":"十五夜望月","intro":"十五夜在这里指中秋之夜；望月引起思乡怀人。","theme":"庭院月色先静静铺开，结尾忽然想到天下望月的人，把一人的乡思推广到众人。","glossary":[{"word":"中庭","meaning":"庭院中"},{"word":"地白","meaning":"月光照得地面发白"},{"word":"树栖鸦","meaning":"树上栖息着乌鸦"},{"word":"冷露","meaning":"清冷露水"},{"word":"无声","meaning":"悄悄地"},{"word":"湿","meaning":"沾湿"},{"word":"桂花","meaning":"桂树花朵"},{"word":"今夜","meaning":"今晚"},{"word":"月明","meaning":"月光明亮"},{"word":"人尽望","meaning":"人们都在仰望"},{"word":"不知","meaning":"不知道"},{"word":"秋思","meaning":"秋夜思亲怀乡的心情"},{"word":"落谁家","meaning":"落在谁家、触动谁"}],"lines":[{"translations":["庭院地面被月光照得发白，树上栖着乌鸦。","清冷露水无声无息地打湿桂花。"],"reading":"不直接写月亮形状，而从地色、露水写出月夜清寂。","clauses":["中庭地白树栖鸦，","冷露无声湿桂花。"]},{"translations":["今晚月亮这样明亮，人们都在仰望。","不知道这秋夜的思念，又落进了谁家。"],"reading":"“落”把无形乡思写得像月光能落下，含蓄而动人。","clauses":["今夜月明人尽望，","不知秋思落谁家。"]}]},"poem-101":{"title":"长歌行","intro":"汉乐府诗，借草木与流水劝人珍惜时间。","theme":"露水、春光、秋衰、江流层层推进，最后点出人生道理；不是恐吓年老，而是提醒及时行动。","glossary":[{"word":"青青","meaning":"茂盛青绿"},{"word":"园中","meaning":"园子里"},{"word":"葵","meaning":"古代常作蔬菜的葵菜，不是向日葵"},{"word":"朝露","meaning":"早晨露水，朝读zhāo"},{"word":"待","meaning":"等待"},{"word":"日晞","meaning":"被太阳晒干，晞读xī"},{"word":"阳春","meaning":"温暖的春天"},{"word":"布","meaning":"遍施"},{"word":"德泽","meaning":"恩惠，形容春阳雨露"},{"word":"万物","meaning":"各种生物"},{"word":"光辉","meaning":"蓬勃光彩"},{"word":"常恐","meaning":"常担心"},{"word":"秋节","meaning":"秋季"},{"word":"焜黄","meaning":"枯黄，焜读kūn"},{"word":"华叶衰","meaning":"花叶衰败，华通花"},{"word":"百川","meaning":"众多河流"},{"word":"东到海","meaning":"向东流入海"},{"word":"何时","meaning":"什么时候"},{"word":"复西归","meaning":"重新向西返回"},{"word":"少壮","meaning":"年轻力壮时"},{"word":"努力","meaning":"勤勉奋进"},{"word":"老大","meaning":"年老时"},{"word":"徒","meaning":"白白地"},{"word":"伤悲","meaning":"悲伤"},{"word":"生","meaning":"产生、呈现"},{"word":"至","meaning":"来到"},{"word":"不","meaning":"没有、不去做"}],"lines":[{"translations":["园中的葵菜长得青绿茂盛。","清晨露珠等待阳光把它晒干。"],"reading":"从眼前植物与露珠入手，让时间流逝可以被看见。","clauses":["青青园中葵，","朝露待日晞。"]},{"translations":["温暖的春天把恩泽洒向万物。","万物都焕发着蓬勃光彩。"],"reading":"“德泽”是拟人化说法，写阳光雨露滋养生命。","clauses":["阳春布德泽，","万物生光辉。"]},{"translations":["却常担心秋天一到。","花叶就会枯黄衰败。"],"reading":"由春盛想到秋衰，提醒美好时光会变化。","clauses":["常恐秋节至，","焜黄华叶衰。"]},{"translations":["许多河流向东流入大海。","什么时候还会向西返回呢？"],"reading":"借水流去而不返，比喻人生时光难以重来，是诗意概括。","clauses":["百川东到海，","何时复西归？"]},{"translations":["年轻时如果不勤勉努力。","年老时便只剩白白悲伤。"],"reading":"结尾点题，倡导珍惜当下；努力可包括学习、劳动和有意义的实践。","clauses":["少壮不努力，","老大徒伤悲！"]}]},"poem-102":{"title":"马诗","intro":"李贺写过一组马诗，这首常标为其五；以马寄托才能获得施展的愿望。","theme":"前两句写适合驰骋的边地秋景，后两句盼装配良马、尽展其能，寓有渴望被赏识之情。","glossary":[{"word":"大漠","meaning":"广阔沙漠"},{"word":"沙如雪","meaning":"月光下沙色像白雪"},{"word":"燕山","meaning":"山名，燕读yān"},{"word":"月似钩","meaning":"弯月像弯钩，也使人联想到兵器"},{"word":"何当","meaning":"什么时候才能"},{"word":"金络脑","meaning":"金饰的马笼头，络脑指笼头"},{"word":"快走","meaning":"迅速奔驰，走是跑"},{"word":"踏","meaning":"踏行"},{"word":"清秋","meaning":"清爽秋天"}],"lines":[{"translations":["辽阔沙漠里的沙子，在月下像白雪。","燕山上方，弯月像一把钩。"],"reading":"两个比喻写出冷峻明亮的秋夜，也营造驰骋边地的氛围。","clauses":["大漠沙如雪，","燕山月似钩。"]},{"translations":["什么时候才能配上金饰的笼头。","在清爽秋日里，尽情飞驰呢？"],"reading":"表面是马的愿望，深层寄托诗人希望施展才能的抱负。","clauses":["何当金络脑，","快走踏清秋。"]}]},"poem-103":{"title":"石灰吟","intro":"吟咏石灰制作过程，以物喻人，表达坚守清白的志向。","theme":"凿、烧、碎写石灰经历，“若等闲”“浑不怕”转成品格语言。白色与清白双关，构成托物言志。","glossary":[{"word":"千锤万凿","meaning":"多次锤打凿击，数字表示多"},{"word":"出深山","meaning":"从深山采出"},{"word":"烈火焚烧","meaning":"经历高温煅烧"},{"word":"若等闲","meaning":"好像平常之事"},{"word":"粉骨碎身","meaning":"身体化为粉末的形象说法，指石灰变化"},{"word":"浑","meaning":"全、完全"},{"word":"不怕","meaning":"不畏惧"},{"word":"要留","meaning":"一定要留下"},{"word":"清白","meaning":"石灰白色，也指人的清白品格"},{"word":"人间","meaning":"人世间"},{"word":"在","meaning":"留存在"}],"lines":[{"translations":["经历无数锤凿，才从深山采出。","再受烈火烧炼，也把它看成平常之事。"],"reading":"把石灰写成能承受考验的人，实际工艺过程与象征意义相叠。","clauses":["千锤万凿出深山，","烈火焚烧若等闲。"]},{"translations":["即使化成粉末，也全不害怕。","只愿把清白留在人世间。"],"reading":"石灰经历的考验象征人生的考验，清白则象征正直的操守。","clauses":["粉骨碎身浑不怕，","要留清白在人间。"]}]},"poem-104":{"title":"竹石","intro":"写扎根岩石中的竹，借竹表达坚韧不屈。","theme":"“咬定”像人的用力动作，“任尔”带坚定语气。重点是环境艰难仍不动摇的精神。","glossary":[{"word":"咬定","meaning":"紧紧抓住、扎住，拟人"},{"word":"青山","meaning":"青翠山岩"},{"word":"不放松","meaning":"不松开"},{"word":"立根","meaning":"扎根"},{"word":"原","meaning":"本来"},{"word":"破岩","meaning":"岩石裂缝"},{"word":"千磨万击","meaning":"经历种种磨难打击"},{"word":"还","meaning":"仍然"},{"word":"坚劲","meaning":"坚韧有力，劲读jìng"},{"word":"任尔","meaning":"任凭你，尔是你"},{"word":"东西南北风","meaning":"各方向吹来的风，泛指各种考验"},{"word":"在","meaning":"处在、位于"},{"word":"中","meaning":"里面"}],"lines":[{"translations":["竹根紧紧扎住青山，不肯放松。","原来它生长在岩石的裂缝里。"],"reading":"“咬”把扎根写得有力量，“破岩”交代生存环境并不轻松。","clauses":["咬定青山不放松，","立根原在破岩中。"]},{"translations":["经历千般磨折、万种打击，仍然坚韧挺拔。","任凭四面八方的风吹来，都不动摇。"],"reading":"风是实景，也象征外来的困难；诗借竹写人的坚守。","clauses":["千磨万击还坚劲，","任尔东西南北风。"]}]},"poem-105":{"title":"采薇（节选）","intro":"选自《诗经·小雅》，是戍卒归途的回忆；这里只读末章常见节选，不等同全诗内容。","theme":"出征春柳与归来冬雪形成时间对照。回家本可欢喜，诗中却饥渴伤悲，显示久役之苦。","glossary":[{"word":"昔","meaning":"从前"},{"word":"我","meaning":"归来的戍卒自称"},{"word":"往","meaning":"出征离去"},{"word":"矣","meaning":"语气词"},{"word":"杨柳依依","meaning":"柳枝柔软低垂的样子"},{"word":"今","meaning":"现在"},{"word":"来","meaning":"归来"},{"word":"思","meaning":"句末语气词，没有思念的实义"},{"word":"雨雪","meaning":"下雪，雨作动词读yù"},{"word":"霏霏","meaning":"雪纷纷飘落的样子"},{"word":"行道","meaning":"走在路上"},{"word":"迟迟","meaning":"缓慢"},{"word":"载","meaning":"又、且，读zài"},{"word":"渴","meaning":"口渴"},{"word":"饥","meaning":"饥饿"},{"word":"伤悲","meaning":"悲伤"},{"word":"莫知","meaning":"没有人知道"},{"word":"哀","meaning":"内心的悲苦"},{"word":"心","meaning":"心里、内心"}],"lines":[{"translations":["从前我离家出征时。","杨柳还轻柔地随风摇曳。"],"reading":"不只是在写好看春景，更用它衬托离别心情与时间变化。","clauses":["昔我往矣，","杨柳依依。"]},{"translations":["如今我终于归来。","却是大雪纷纷飘落。"],"reading":"“思”是语气词；“雨”是下的意思，不能译成下雨又下雪。","clauses":["今我来思，","雨雪霏霏。"]},{"translations":["走在路上，脚步缓慢。","又渴，又饿。"],"reading":"短句写长途归来的疲惫，不是简单的凯旋欢歌。","clauses":["行道迟迟，","载渴载饥。"]},{"translations":["我的心里充满悲伤。","却没有人懂得我的苦痛。"],"reading":"结尾直抒内心，久别归来与战争创伤交织，情绪十分复杂。","clauses":["我心伤悲，","莫知我哀！"]}]},"poem-106":{"title":"送元二使安西","intro":"送元二出使安西；元二是友人，安西是唐代边地行政区域。","theme":"先写雨后客舍柳色，再写临别劝酒；柳的依依与西去的遥远共同映衬珍惜友情。","glossary":[{"word":"渭城","meaning":"秦汉古城，在今陕西咸阳附近"},{"word":"朝雨","meaning":"清晨的雨，朝读zhāo"},{"word":"浥","meaning":"沾湿，读yì"},{"word":"轻尘","meaning":"轻细尘土"},{"word":"客舍","meaning":"旅馆"},{"word":"青青","meaning":"清新青翠"},{"word":"柳色新","meaning":"柳树经雨显得新鲜"},{"word":"劝君","meaning":"劝你，君指元二"},{"word":"更尽","meaning":"再喝完"},{"word":"一杯酒","meaning":"送别的一杯酒"},{"word":"西出","meaning":"向西走出"},{"word":"阳关","meaning":"古代关口"},{"word":"无故人","meaning":"难再遇到老朋友"}],"lines":[{"translations":["渭城早晨的雨，沾湿了轻细尘土。","旅馆旁的柳树经雨洗过，显得格外青翠。"],"reading":"清新景色不减离愁，反而使送别时刻更令人难忘。","clauses":["渭城朝雨浥轻尘，","客舍青青柳色新。"]},{"translations":["请你再饮完这一杯送别酒。","向西出了阳关，就难再遇见老朋友了。"],"reading":"“更”说明酒已喝过仍不忍别，“无故人”突出友人前路遥远。","clauses":["劝君更尽一杯酒，","西出阳关无故人。"]}]},"poem-107":{"title":"春夜喜雨","intro":"写春夜好雨，喜意从雨的及时、有益一直贯穿到对天明的想象。","theme":"拟人把雨写得懂时节，潜与细写润物无声，最后想象雨后花城，喜悦含蓄而丰足。","glossary":[{"word":"知时节","meaning":"仿佛懂得适宜时令"},{"word":"当春","meaning":"正值春天"},{"word":"乃","meaning":"就"},{"word":"发生","meaning":"滋生、到来，这里指雨随春而降"},{"word":"随风","meaning":"随着风"},{"word":"潜","meaning":"悄悄地，读qián"},{"word":"入夜","meaning":"进入夜里"},{"word":"润物","meaning":"滋润万物"},{"word":"细","meaning":"细密轻柔"},{"word":"无声","meaning":"没有明显声响"},{"word":"野径","meaning":"郊野小路"},{"word":"云俱黑","meaning":"乌云与周围一片昏黑"},{"word":"江船","meaning":"江上船只"},{"word":"火独明","meaning":"只有灯火明亮"},{"word":"晓看","meaning":"天亮时看"},{"word":"红湿处","meaning":"被雨打湿的红花所在"},{"word":"花重","meaning":"花含雨水而显沉，重读zhòng"},{"word":"锦官城","meaning":"成都别称"},{"word":"好雨","meaning":"应时降落、滋养万物的春雨"}],"lines":[{"translations":["好雨仿佛知道合适的时节。","正值春天，就应时而来。"],"reading":"“知”是拟人，“好”来自雨能滋养春生万物。","clauses":["好雨知时节，","当春乃发生。"]},{"translations":["它随着春风悄悄进入夜里。","细细滋润万物，没有明显声响。"],"reading":"“潜”“细”“无声”写它温柔地发挥作用，包含诗人的赞赏。","clauses":["随风潜入夜，","润物细无声。"]},{"translations":["郊野小路与低云，都隐在昏黑之中。","只有江船上的灯火独自明亮。"],"reading":"一暗一明的对照，使夜雨中的空间可感。","clauses":["野径云俱黑，","江船火独明。"]},{"translations":["天明再看，那被雨润湿的红花。","成都城里的花朵，定会饱含雨水、更加丰美。"],"reading":"后两句是对明晨的想象，不是已经看见天亮后的景象。","clauses":["晓看红湿处，","花重锦官城。"]}]},"poem-108":{"title":"早春呈水部张十八员外","intro":"呈是呈送；水部张十八员外指在水部任职的张籍；写京城早春细微美感。","theme":"小雨细润、草色若有若无，是早春特征。诗偏爱初生之美，认为胜过暮春浓柳。","glossary":[{"word":"天街","meaning":"京城街道"},{"word":"小雨","meaning":"细雨"},{"word":"润如酥","meaning":"滋润得像酥，酥是乳制品，借喻细腻柔润"},{"word":"草色","meaning":"初生小草的绿色"},{"word":"遥看","meaning":"远远望去"},{"word":"近却无","meaning":"走近看反而不显眼"},{"word":"最是","meaning":"正是"},{"word":"一年","meaning":"一年中"},{"word":"春好处","meaning":"春光最好的时候"},{"word":"绝胜","meaning":"远远胜过"},{"word":"烟柳","meaning":"柳叶茂密、如烟的柳树"},{"word":"满皇都","meaning":"遍布京城"}],"lines":[{"translations":["京城街头的细雨，滋润得像细腻的酥。","草色远看隐约成片，走近却难看清。"],"reading":"初生草芽稀小，远看叠成浅绿，近看间有泥土；不是草突然消失。","clauses":["天街小雨润如酥，","草色遥看近却无。"]},{"translations":["这正是一年春光最美的时候。","在诗人看来，远胜过柳色如烟、满城浓绿的暮春。"],"reading":"“绝胜”是诗人的审美偏爱，赞美春天刚开始时的清新。","clauses":["最是一年春好处，","绝胜烟柳满皇都。"]}]},"poem-109":{"title":"江上渔者","intro":"渔者是捕鱼的人；诗把享用鱼的人与捕鱼者的危险放在一起。","theme":"前两句写食客只爱美味，后两句请看小舟搏浪，提醒尊重劳动者、看见成果背后的辛苦。","glossary":[{"word":"江上","meaning":"江边、江面一带"},{"word":"往来人","meaning":"来来往往的人"},{"word":"但","meaning":"只"},{"word":"爱","meaning":"喜欢"},{"word":"鲈鱼","meaning":"一种食用鱼，鲈读lú"},{"word":"美","meaning":"味道鲜美"},{"word":"君看","meaning":"你看"},{"word":"一叶舟","meaning":"像叶片般小的船"},{"word":"出没","meaning":"时隐时现"},{"word":"风波里","meaning":"风浪之中"}],"lines":[{"translations":["江边来来往往的人。","只喜爱鲈鱼的鲜美滋味。"],"reading":"“但”有提醒和批评意味：只见美味，却未见劳作。","clauses":["江上往来人，","但爱鲈鱼美。"]},{"translations":["你看那一叶小船。","正随着风浪，时隐时现。"],"reading":"不直接说危险，而以小舟与风波的悬殊让读者感到风险。","clauses":["君看一叶舟，","出没风波里。"]}]},"poem-110":{"title":"泊船瓜洲","intro":"泊船是停船；瓜洲与京口隔长江相望，钟山是诗人眷恋的家园所在。","theme":"空间上看似相近，情感上却难立即归家。春风使江岸绿，也唤起归乡之问。","glossary":[{"word":"京口","meaning":"今江苏镇江"},{"word":"瓜洲","meaning":"长江北岸古渡口，今扬州附近"},{"word":"一水间","meaning":"隔着一条江水，间表示间隔"},{"word":"钟山","meaning":"今南京紫金山"},{"word":"只隔","meaning":"仅仅隔着"},{"word":"数重山","meaning":"几层山，重读chóng"},{"word":"春风","meaning":"春天的风"},{"word":"又","meaning":"再一次"},{"word":"绿","meaning":"使……变绿，是动词"},{"word":"江南岸","meaning":"长江南岸"},{"word":"明月","meaning":"月亮"},{"word":"何时","meaning":"什么时候"},{"word":"照我还","meaning":"照着我返回家乡，还读huán"}],"lines":[{"translations":["京口与瓜洲，只隔着一道江水。","钟山也不过隔着几重山。"],"reading":"“只”“数”显出故乡似乎近在眼前，衬托心中归意。","clauses":["京口瓜洲一水间，","钟山只隔数重山。"]},{"translations":["春风又把江南岸吹绿了。","明月什么时候，才能照着我回家呢？"],"reading":"“绿”把春天带来的变化写活；问月实际是在问自己的归期。","clauses":["春风又绿江南岸，","明月何时照我还。"]}]},"poem-111":{"title":"游园不值","intro":"游园是到园子游赏；不值是没有遇到主人，不是“不值得”。","theme":"扣门不开原有遗憾，墙外红杏却带来惊喜。春色无法完全被墙关住，表现自然生机的蓬勃。","glossary":[{"word":"应怜","meaning":"大概是爱惜，应表示猜想"},{"word":"屐齿","meaning":"木屐底下的齿，屐读jī"},{"word":"印苍苔","meaning":"在青苔上踩出印迹"},{"word":"小扣","meaning":"轻轻敲门"},{"word":"柴扉","meaning":"柴木做的门，扉读fēi"},{"word":"久不开","meaning":"久久没人来开"},{"word":"春色满园","meaning":"园内春景繁盛"},{"word":"关不住","meaning":"无法全部遮住"},{"word":"一枝红杏","meaning":"一枝红杏花"},{"word":"出墙来","meaning":"伸出墙外"}],"lines":[{"translations":["大概是主人爱惜青苔，怕木屐踩下印子吧。","我轻敲柴门，很久也没有人开。"],"reading":"“应”说明这是猜测，不能断言主人故意拒客。","clauses":["应怜屐齿印苍苔，","小扣柴扉久不开。"]},{"translations":["园里春色满满，终究关不住。","一枝红杏花，已经伸到墙外来了。"],"reading":"由局部一枝推想到满园春光，虽未入园仍得春意。","clauses":["春色满园关不住，","一枝红杏出墙来。"]}]},"poem-112":{"title":"卜算子·送鲍浩然之浙东","intro":"卜算子是词牌；鲍浩然是送别友人；之是到、往，浙东是目的地。","theme":"把山水比作眉眼，再用“送春”“送君”“和春住”串联，化离别为祝福，构思轻巧新鲜。","glossary":[{"word":"水是眼波横","meaning":"流水像美人横流的眼波"},{"word":"山是眉峰聚","meaning":"山峦像聚起的眉峰"},{"word":"欲问","meaning":"若要问"},{"word":"行人","meaning":"将远行的人，指鲍浩然"},{"word":"那边","meaning":"哪里、哪边"},{"word":"眉眼盈盈处","meaning":"山水秀美的地方，盈盈形容美好"},{"word":"才始","meaning":"刚刚"},{"word":"送春归","meaning":"送走春天"},{"word":"又","meaning":"接着"},{"word":"送君去","meaning":"送你离开"},{"word":"若","meaning":"如果"},{"word":"江南","meaning":"长江以南地区"},{"word":"赶上春","meaning":"赶上尚存的春色"},{"word":"千万","meaning":"务必"},{"word":"和春住","meaning":"与春光同住，含祝福"},{"word":"去","meaning":"前往"},{"word":"送君归去","meaning":"送你返回要去的地方，君是对友人的尊称"},{"word":"到","meaning":"到达"}],"lines":[{"translations":["水像横流的眼波。","山像轻聚的眉峰。"],"reading":"把常见的“眉像山、眼像水”倒过来写，让山水有人的神情。","clauses":["水是眼波横，","山是眉峰聚。"]},{"translations":["若问远行的人要到哪里。","正是那山水清秀、眉眼含情的地方。"],"reading":"“眉眼”承接山水，不必只认作某一位真实人物。","clauses":["欲问行人去那边？","眉眼盈盈处。"]},{"translations":["才刚送别了春天。","又要送你远行。"],"reading":"两次“送”把季节更替与朋友离别相连，惜春惜友重叠。","clauses":["才始送春归，","又送君归去。"]},{"translations":["如果到江南还能赶上春光。","请一定与美好春光同住。"],"reading":"结尾将不舍化作祝福，是拟人化的想象，充满温情。","clauses":["若到江南赶上春，","千万和春住。"]}]},"poem-113":{"title":"浣溪沙（山下兰芽短浸溪）","intro":"浣溪沙是词牌；写游清泉寺所见，并由溪水西流生发乐观感慨。","theme":"上片写清新溪景，下片反用流水与衰老的常见联想。保持青春精神，不等于肉体能返老还童。","glossary":[{"word":"兰芽","meaning":"兰草新生嫩芽"},{"word":"短浸溪","meaning":"初生嫩芽低矮，浸润在溪水边"},{"word":"松间","meaning":"松林之间"},{"word":"沙路","meaning":"沙石小路"},{"word":"净无泥","meaning":"干净没有泥泞"},{"word":"潇潇","meaning":"这里写细雨声，有版本作萧萧"},{"word":"暮雨","meaning":"傍晚的雨"},{"word":"子规","meaning":"杜鹃鸟"},{"word":"啼","meaning":"鸣叫"},{"word":"谁道","meaning":"谁说，反问"},{"word":"人生","meaning":"人的生命历程"},{"word":"无再少","meaning":"不能重新拥有年轻精神，少读shào"},{"word":"尚能西","meaning":"还能向西流，西是向西"},{"word":"休","meaning":"不要"},{"word":"将","meaning":"拿、因"},{"word":"白发","meaning":"借指衰老"},{"word":"唱黄鸡","meaning":"借鸡报晓感叹时光流逝，关联白居易诗意"},{"word":"山下","meaning":"山脚下"},{"word":"门前流水","meaning":"寺门前向西流动的溪水"}],"lines":[{"translations":["山下初生的兰芽低矮，浸润在溪水旁。","松林间沙路洁净，没有泥泞。","傍晚细雨潇潇，传来杜鹃鸣叫。"],"reading":"清新景物与细雨鸟声组合，情调幽静，也为后面的振作作铺垫。","clauses":["山下兰芽短浸溪，","松间沙路净无泥，","潇潇暮雨子规啼。"]},{"translations":["谁说人生就不能再有年轻的精神？","门前的溪水，不也还能向西流吗！","不要因白发而一味感叹报晓鸡声、时光流逝。"],"reading":"西流的溪水是真景，精神可以振作是由景引出的比喻，不能解释成生理年龄倒转。","clauses":["谁道人生无再少？","门前流水尚能西！","休将白发唱黄鸡。"]}]},"poem-114":{"title":"清平乐（春归何处）","intro":"清平乐是词牌，乐读yuè；这首词写惜春寻春。","theme":"连续设问与拟人让春天像失踪的朋友，黄鹂又像知情者。末尾鸟飞花间，留给读者余味。","glossary":[{"word":"春归","meaning":"春天离去"},{"word":"何处","meaning":"什么地方"},{"word":"寂寞","meaning":"因春去而冷清，也有独自感受之意"},{"word":"无行路","meaning":"没有留下可寻的踪迹"},{"word":"若有","meaning":"如果有"},{"word":"知","meaning":"知道"},{"word":"唤取","meaning":"呼唤回来"},{"word":"归来","meaning":"回来"},{"word":"同住","meaning":"一起留下"},{"word":"无踪迹","meaning":"没有痕迹"},{"word":"谁知","meaning":"谁能知道"},{"word":"除非","meaning":"除非问"},{"word":"黄鹂","meaning":"鸟名"},{"word":"百啭","meaning":"婉转鸣叫很多声，啭读zhuàn"},{"word":"无人能解","meaning":"没有人听得懂"},{"word":"因风","meaning":"顺着风"},{"word":"飞过","meaning":"飞越"},{"word":"蔷薇","meaning":"花木名，读qiáng wēi"},{"word":"人","meaning":"能知道春去向的人"},{"word":"春去处","meaning":"春天离去后所在的地方"},{"word":"春","meaning":"春天，也指春光"},{"word":"问取","meaning":"问一问，取是语助成分"}],"lines":[{"translations":["春天去了哪里？","周围冷清，又寻不到它离去的路。"],"reading":"把季节更替写成朋友离去，惜春的心情因此亲切可感。","clauses":["春归何处？","寂寞无行路。"]},{"translations":["如果有人知道春天去了何处。","请把它叫回来，与我们同住。"],"reading":"愿望明知难实现，却真切表现诗人留恋春光。","clauses":["若有人知春去处，","唤取归来同住。"]},{"translations":["春天没有留下踪迹，谁会知道呢？","除非去问一问黄鹂。"],"reading":"一问再问，想象鸟儿或许知道季节秘密，构思活泼。","clauses":["春无踪迹谁知？","除非问取黄鹂。"]},{"translations":["黄鹂婉转叫了许多声，可谁也听不懂。","它便顺着风，飞过了蔷薇花丛。"],"reading":"问题仍无答案，鸟与花让画面继续流动，惜春情意也没有说尽。","clauses":["百啭无人能解，","因风飞过蔷薇。"]}]}};
